INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_kor_u1_L01_basic#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',1,'mc','auto','작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":1,"kind":"mc","stem":"작품에서 「인상적인 부분」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분","correct":true},{"t":"글자 수가 가장 많은 부분","mis":"K5-2-u1-X01"},{"t":"선생님이 정해 주신 한 부분","mis":"K5-2-u1-X02"},{"t":"어려운 낱말이 가장 많이 든 부분","mis":"K5-2-u1-X01"}],"explanation":["길이와는 관계없어요.","정해 준 정답이 있는 게 아니에요.","내 마음이 움직인 곳이에요."]}'::jsonb),
('g5_2_kor_u1_L01_basic#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'ox','auto','같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"같은 시를 읽으면 모든 사람의 인상적인 부분이 똑같아요.","answer":"X","reason_options":[{"t":"사람마다 마음에 남는 부분이 다를 수 있기 때문에","correct":true},{"t":"시에는 하나로 정해진 인상적인 부분이 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["같은 시도 다르게 남아요.","정답이 하나로 정해져 있지 않아요.","그래서 서로 이야기 나눌 거리가 생겨요."]}'::jsonb),
('g5_2_kor_u1_L01_basic#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C2',1,'mc','auto','시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?',ARRAY['K5-2-u1-X15','K5-2-u1-X02','K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C2","difficulty":1,"kind":"mc","stem":"시우와 나은이가 「우산 셋」에서 고른 부분을 보고 알 수 있는 것은 어느 것인가요?","options":[{"t":"같은 시를 읽어도 인상적인 부분이 다를 수 있다","correct":true},{"t":"둘 중 한 사람은 시를 잘못 읽었다","mis":"K5-2-u1-X15"},{"t":"인상적인 부분은 첫째 연에만 있다","mis":"K5-2-u1-X02"},{"t":"긴 연을 고른 사람이 더 잘 읽었다","mis":"K5-2-u1-X01"}],"explanation":["잘못 읽은 사람은 없어요.","어느 연이든 될 수 있어요.","고른 곳이 달라도 둘 다 까닭이 있어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb),
('g5_2_kor_u1_L01_basic#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',1,'blank','auto','인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.',ARRAY['K5-2-u1-X01','K5-2-u1-X04']::text[],false,'{"seq":4,"concept":"K5-2-u1-C3","difficulty":1,"kind":"blank","stem":"인상적인 부분을 말할 때에는 고른 부분과 함께 그 부분이 인상적인 (     )을/를 말해요.","options":[{"t":"까닭","correct":true},{"t":"글자 수","mis":"K5-2-u1-X01"},{"t":"쪽수","mis":"K5-2-u1-X04"},{"t":"지은이 나이","mis":"K5-2-u1-X04"}],"explanation":["글자 수는 묻지 않아요.","쪽수는 까닭이 아니에요.","왜 마음에 남았는지 말해요."]}'::jsonb),
('g5_2_kor_u1_L01_basic#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C1',2,'mc','auto','「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":5,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"「우산 셋」을 읽고 고른 인상적인 부분 가운데 「궁금증이 생긴 곳」에 가장 가까운 말은 어느 것인가요?","options":[{"t":"「파란 우산은 왜 꽃집 앞에 멈췄을까?」 하고 궁금했어.","correct":true},{"t":"「빨간 우산 이야기가 제일 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「그냥 넷째 연이 좋아.」","mis":"K5-2-u1-X03"},{"t":"「우산이 세 개라서 골랐어.」","mis":"K5-2-u1-X04"}],"explanation":["길이는 까닭이 못 돼요.","까닭이 빠졌어요.","궁금증이 생긴 곳도 인상적인 부분이에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb),
('g5_2_kor_u1_L01_basic#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'mc','auto','나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":6,"concept":"K5-2-u1-C3","difficulty":2,"kind":"mc","stem":"나은이가 「친구 우산 밑으로 쏙 들어갔다」를 고른 까닭은 무엇인가요?","options":[{"t":"짝꿍이 우산을 씌워 준 일이 떠올라서","correct":true},{"t":"빗물 튀는 소리가 들리는 것 같아서","mis":"K5-2-u1-X03"},{"t":"시의 맨 처음 연이라서","mis":"K5-2-u1-X04"},{"t":"빨간색을 가장 좋아해서","mis":"K5-2-u1-X04"}],"explanation":["그건 시우가 든 까닭이에요.","그 행은 처음 연이 아니에요.","내 경험이 떠오른 것도 까닭이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb),
('g5_2_kor_u1_L01_basic#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',2,'match','auto','작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u1-C4","difficulty":2,"kind":"match","stem":"작품의 종류와 인상적인 부분을 찾을 때 살필 것을 알맞게 이으세요.","pairs":[{"l":"시","r":"표현 · 말하는 이의 마음 · 분위기"},{"l":"이야기","r":"인물 · 사건 · 인물의 말과 행동"},{"l":"서평","r":"책에 대한 평가와 그 까닭"}],"mis":"K5-2-u1-X05","explanation":["시는 표현과 마음을 봐요.","이야기는 인물과 사건을 봐요.","서평은 평가를 봐요."]}'::jsonb),
('g5_2_kor_u1_L01_basic#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C3',2,'error','auto','「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X04']::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「우산 셋」을 읽고 친구들이 한 말이에요. 인상적인 부분을 알맞게 말하지 못한 것은 어느 것인가요?","options":[{"t":"「넷째 연이 인상적이야. 이유는 없어.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「넷째 연이 인상적이야. 하늘이 우산을 말려 준다는 말이 다정하게 느껴져.」","mis":"K5-2-u1-X03"},{"t":"「셋째 연이 인상적이야. 친구를 챙기는 모습이 따뜻해서.」","mis":"K5-2-u1-X04"}],"explanation":["까닭이 시 속 말과 이어져요.","까닭이 장면과 이어져요.","부분만 있고 까닭이 없어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb),
('g5_2_kor_u1_L01_basic#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C5',2,'mc','auto','이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05']::text[],false,'{"seq":9,"concept":"K5-2-u1-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배울 내용의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"시 → 이야기 → 서평 쓰기 → 「이달의 책」 고르기","correct":true},{"t":"서평 쓰기 → 시 → 이야기 → 「이달의 책」 고르기","mis":"K5-2-u1-X05"},{"t":"「이달의 책」 고르기 → 서평 쓰기 → 시","mis":"K5-2-u1-X05"},{"t":"이야기 → 「이달의 책」 고르기 → 시","mis":"K5-2-u1-X05"}],"explanation":["서평은 이야기를 읽은 뒤에 써요.","「이달의 책」은 맨 끝에 골라요.","시에서 시작해 책으로 넓혀요."]}'::jsonb),
('g5_2_kor_u1_L01_basic#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_basic','lesson_basic','K5-2-u1-C4',3,'mc','auto','「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X03','K5-2-u1-X15']::text[],false,'{"seq":10,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"「작품에 대한 의견을 나누어요」 단원에서 가장 중요하게 기를 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"까닭을 들어 내 생각을 말하고 친구의 다른 생각도 귀 기울여 듣는 태도","correct":true},{"t":"하나뿐인 정답 부분을 먼저 찾아 외우는 태도","mis":"K5-2-u1-X02"},{"t":"까닭은 빼고 좋아하는 부분만 빨리 말하는 태도","mis":"K5-2-u1-X03"},{"t":"나와 다른 의견은 틀렸다고 알려 주는 태도","mis":"K5-2-u1-X15"}],"explanation":["정답 부분이 따로 있지 않아요.","까닭이 함께 가야 해요.","다른 의견에서 배울 수 있어요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#1','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',2,'mc','auto','다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X01','K5-2-u1-X35']::text[],false,'{"seq":1,"concept":"K5-2-u1-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 인상적인 부분이 될 수 없는 것은 어느 것인가요?","options":[{"t":"읽었는데 아무 느낌도 남지 않은 부분","correct":true},{"t":"내 경험이 떠올라 고개가 끄덕여진 부분","mis":"K5-2-u1-X08"},{"t":"「왜 그럴까?」 하고 궁금해진 부분","mis":"K5-2-u1-X01"},{"t":"짧지만 오래 기억에 남는 문장","mis":"K5-2-u1-X35"}],"explanation":["경험이 떠오른 곳도 인상적이에요.","궁금증이 생긴 곳도 인상적이에요.","짧은 문장도 될 수 있어요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#2','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',2,'ox','auto','정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":2,"concept":"K5-2-u1-C4","difficulty":2,"kind":"ox","stem":"정답이 하나가 아니니까 작품과 아무 관계없는 까닭을 대도 괜찮아요.","answer":"X","reason_options":[{"t":"까닭은 작품 속 말이나 장면, 그와 이어진 내 경험과 닿아 있어야 하기 때문에","correct":true},{"t":"인상적인 부분은 사람마다 다르니 무엇이든 까닭이 되기 때문에","mis":"K5-2-u1-X04"}],"mis":"K5-2-u1-X04","explanation":["정답이 없다는 말이 아무거나라는 뜻은 아니에요.","작품과 이어져야 서로 이해해요.","열려 있되 까닭은 작품에 닿아요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#3','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',3,'mc','auto','시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?',ARRAY['K5-2-u1-X04']::text[],false,'{"seq":3,"concept":"K5-2-u1-C3","difficulty":3,"kind":"mc","stem":"시우의 까닭 「빗물 튀는 소리가 들리는 것 같아」는 시의 어느 말과 이어지나요?","options":[{"t":"「폴짝폴짝」","correct":true},{"t":"「느릿느릿」","mis":"K5-2-u1-X04"},{"t":"「나란히」","mis":"K5-2-u1-X04"},{"t":"「쏙」","mis":"K5-2-u1-X04"}],"explanation":["「느릿느릿」은 파란 우산이에요.","「나란히」는 넷째 연이에요.","뛰어 건너는 소리를 흉내 낸 말이에요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb),
('g5_2_kor_u1_L01_challenge#4','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'mc','auto','시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X08','K5-2-u1-X15']::text[],false,'{"seq":4,"concept":"K5-2-u1-C2","difficulty":3,"kind":"mc","stem":"시우와 나은이의 말에서 알 수 있는 생각으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고른 부분이 달라도 까닭이 있으면 둘 다 의미 있는 감상이다","correct":true},{"t":"먼저 말한 시우의 감상이 정답이다","mis":"K5-2-u1-X02"},{"t":"나은이는 시와 상관없는 이야기를 했다","mis":"K5-2-u1-X08"},{"t":"고른 부분이 다르면 다시 읽어 하나로 맞춰야 한다","mis":"K5-2-u1-X15"}],"explanation":["먼저 말했다고 정답이 아니에요.","경험이 떠오른 것도 까닭이에요.","하나로 맞출 필요가 없어요."],"asset":{"type":"speech","turns":[{"who":"시우","text":"나는 「폴짝폴짝 웅덩이를 건너고」가 인상적이야. 빗물 튀는 소리가 들리는 것 같아."},{"who":"나은","text":"나는 「친구 우산 밑으로 쏙」이 좋아. 지난번에 짝꿍이 나를 씌워 준 일이 떠올랐거든."},{"who":"시우","text":"같은 시인데 우리가 고른 데가 다르네."},{"who":"나은","text":"응, 그래도 둘 다 왜 골랐는지 까닭이 있잖아."}]}}'::jsonb),
('g5_2_kor_u1_L01_challenge#5','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C4',3,'mc','auto','이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X01']::text[],false,'{"seq":5,"concept":"K5-2-u1-C4","difficulty":3,"kind":"mc","stem":"이야기를 읽고 인상적인 부분을 찾을 때 가장 먼저 살필 것은 어느 것인가요?","options":[{"t":"인물이 처한 상황과 그때 한 말이나 행동","correct":true},{"t":"행마다 반복되는 흉내 내는 말의 개수","mis":"K5-2-u1-X05"},{"t":"책의 쪽수와 글씨 크기","mis":"K5-2-u1-X01"},{"t":"연과 행이 몇 개인지","mis":"K5-2-u1-X05"}],"explanation":["그건 시의 표현을 볼 때예요.","쪽수는 감상과 관계없어요.","이야기는 인물과 사건을 따라가요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#6','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',3,'error','auto','「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X16','K5-2-u1-X03']::text[],false,'{"seq":6,"concept":"K5-2-u1-C2","difficulty":3,"kind":"error","stem":"「우산 셋」을 읽고 나눈 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다들 첫째 연을 골라야 맞아. 시의 처음이니까.」","correct":true,"mis_target":"K5-2-u1-X02"},{"t":"「나는 넷째 연이 다정해서 골랐는데, 네가 고른 연도 들어 볼래.」","mis":"K5-2-u1-X16"},{"t":"「나는 셋째 연을 골랐어. 친구를 챙기는 모습이 좋아서.」","mis":"K5-2-u1-X03"}],"explanation":["다른 생각도 들으려 해요.","부분과 까닭을 함께 말했어요.","처음 연이 정답인 것은 아니에요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb),
('g5_2_kor_u1_L01_challenge#7','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C5',3,'mc','auto','이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X05','K5-2-u1-X34','K5-2-u1-X31']::text[],false,'{"seq":7,"concept":"K5-2-u1-C5","difficulty":3,"kind":"mc","stem":"이 단원의 마지막 활동인 「이달의 책」 고르기에 앞에서 배운 것이 쓰이는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"책을 추천할 때 인상적인 부분과 그 까닭을 들어 말해야 하기 때문에","correct":true},{"t":"「이달의 책」은 시집만 고를 수 있기 때문에","mis":"K5-2-u1-X05"},{"t":"책 제목만 알면 고를 수 있기 때문에","mis":"K5-2-u1-X34"},{"t":"가장 두꺼운 책을 골라야 하기 때문에","mis":"K5-2-u1-X31"}],"explanation":["시집만 고르는 게 아니에요.","제목만으로는 추천이 안 돼요.","두께는 기준이 아니에요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#8','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C3',4,'essay','teacher','「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C3","difficulty":4,"kind":"essay","stem":"「우산 셋」에서 내가 고른 인상적인 부분을 하나 쓰고, 그 부분이 인상적인 까닭을 시 속 말과 이어서 쓰세요.","answer_guide":{"answer":"예: 넷째 연 「비 그친 하늘이 / 세 우산을 나란히 말려 준다」가 인상적이다. 하늘이 사람처럼 우산을 말려 준다는 말에서 비가 그친 뒤의 맑고 다정한 느낌이 들기 때문이다. 서로 다른 길을 간 우산들이 마지막에 나란히 놓이는 모습도 따뜻하게 느껴졌다.","scoring_points":["인상적인 부분을 시에서 골라 썼는가","까닭을 썼는가","까닭이 시 속 말이나 장면과 이어지는가"]},"explanation":["한 부분을 골라요.","왜 남았는지 써요.","시 속 말과 이어요."],"asset":{"type":"passage","lines":["노란 우산은 / 폴짝폴짝 웅덩이를 건너고","파란 우산은 / 느릿느릿 꽃집 앞에 멈추고","빨간 우산은 / 친구 우산 밑으로 쏙 들어갔다","비 그친 하늘이 / 세 우산을 나란히 말려 준다"],"title":"시 「우산 셋」"}}'::jsonb),
('g5_2_kor_u1_L01_challenge#9','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C2',4,'essay','teacher','「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C2","difficulty":4,"kind":"essay","stem":"「인상적인 부분에는 정답이 없지만, 아무거나 골라도 되는 것은 아니다」라는 말의 뜻을 쓰세요.","answer_guide":{"answer":"예: 같은 작품을 읽어도 사람마다 경험과 생각이 달라 마음에 남는 부분이 다를 수 있으므로 정답이 하나로 정해져 있지 않다. 하지만 그 부분이 왜 인상적인지 작품 속 말이나 장면, 그와 이어진 내 경험으로 까닭을 대야 친구도 내 생각을 이해할 수 있다. 까닭 없이 고르거나 작품과 상관없는 까닭을 대는 것은 감상이라고 하기 어렵다.","scoring_points":["정답이 없는 까닭을 썼는가","까닭이 작품과 이어져야 함을 썼는가","두 가지를 함께 정리했는가"]},"explanation":["사람마다 다른 까닭을 떠올려요.","까닭의 조건을 써요.","두 말을 이어 정리해요."]}'::jsonb),
('g5_2_kor_u1_L01_challenge#10','kor',5,2,'u1','L01','g5_2_kor_u1_L01_challenge','lesson_challenge','K5-2-u1-C1',4,'essay','teacher','내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C1","difficulty":4,"kind":"essay","stem":"내가 재미있게 읽었던 이야기나 시를 하나 떠올려, 인상적인 부분이 「마음이 움직인 곳 · 궁금증이 생긴 곳 · 깨달음이 생긴 곳」 가운데 어디에 가까운지 쓰고 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 동화에서 주인공이 잃어버린 강아지를 찾으려고 비 오는 밤에 골목을 헤매는 장면이 인상적이었다. 마음이 움직인 곳에 가깝다. 강아지를 애타게 부르는 주인공의 목소리가 들리는 것 같아 나도 가슴이 조마조마했기 때문이다.","scoring_points":["작품과 인상적인 부분을 썼는가","세 가지 가운데 하나를 골랐는가","까닭을 작품과 이어 썼는가"]},"explanation":["읽은 작품을 떠올려요.","어떤 마음이 들었는지 골라요.","까닭을 붙여요."]}'::jsonb),
('g5_2_kor_u1_L02_basic#1','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C6',1,'mc','auto','「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?',ARRAY['K5-2-u1-X06','K5-2-u1-X09']::text[],false,'{"seq":1,"concept":"K5-2-u1-C6","difficulty":1,"kind":"mc","stem":"「말의 온도」에서 따뜻한 말을 들었을 때의 모습은 어떠한가요?","options":[{"t":"두 볼이 발그레해진다","correct":true},{"t":"어깨가 움츠러든다","mis":"K5-2-u1-X06"},{"t":"마음이 따끔따끔하다","mis":"K5-2-u1-X06"},{"t":"발자국이 찍힌다","mis":"K5-2-u1-X09"}],"explanation":["차가운 말을 들었을 때예요.","뾰족한 말을 들었을 때예요.","따뜻한 말은 볼을 발그레하게 해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
('g5_2_kor_u1_L02_basic#2','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C9',1,'mc','auto','「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X11','K5-2-u1-X09','K5-2-u1-X06']::text[],false,'{"seq":2,"concept":"K5-2-u1-C9","difficulty":1,"kind":"mc","stem":"「말의 온도」의 주제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 듣는 사람의 마음에 남으니 조심해서 말해야 한다","correct":true},{"t":"겨울에는 따뜻하게 입어야 한다","mis":"K5-2-u1-X11"},{"t":"발자국은 사뿐사뿐 남겨야 한다","mis":"K5-2-u1-X09"},{"t":"뾰족한 물건은 위험하다","mis":"K5-2-u1-X06"}],"explanation":["온도는 날씨 이야기가 아니에요.","발자국은 빗댄 말이에요.","마지막 연에 하고 싶은 말이 드러나요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
('g5_2_kor_u1_L02_basic#3','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C7',1,'ox','auto','「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X01']::text[],false,'{"seq":3,"concept":"K5-2-u1-C7","difficulty":1,"kind":"ox","stem":"「따끔따끔」처럼 느낌을 흉내 낸 말도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"독특하고 재미있는 표현은 읽는 사람의 마음에 남기 쉽기 때문에","correct":true},{"t":"흉내 내는 말은 쉬운 말이라 인상적일 수 없기 때문에","mis":"K5-2-u1-X01"}],"mis":"K5-2-u1-X01","explanation":["쉬운 말도 마음에 남아요.","느낌이 살아나는 표현이에요.","표현이 주는 느낌까지 말해요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
