('g5_2_kor_u1_L02_basic#5','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C11',2,'mc','auto','「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":5,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「말은 마음에 찍히는 발자국」에서 말과 발자국의 닮은 점은 무엇인가요?","options":[{"t":"한번 남으면 쉽게 지워지지 않는다","correct":true},{"t":"둘 다 발로 만든다","mis":"K5-2-u1-X09"},{"t":"둘 다 눈 위에만 생긴다","mis":"K5-2-u1-X09"},{"t":"둘 다 소리가 크다","mis":"K5-2-u1-X09"}],"explanation":["글자 그대로 읽지 않아요.","눈 이야기가 아니에요.","마음에 남는다는 점이 닮았어요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
('g5_2_kor_u1_L02_basic#6','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C8',2,'error','auto','「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X08','K5-2-u1-X03','K5-2-u1-X09']::text[],false,'{"seq":6,"concept":"K5-2-u1-C8","difficulty":2,"kind":"error","stem":"「말의 온도」를 읽고 친구들이 말한 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「내 경험이 떠올라 고른 건 시와 상관없으니 까닭이 안 돼.」","correct":true,"mis_target":"K5-2-u1-X08"},{"t":"「친구에게 따뜻한 말을 듣고 볼이 뜨거워진 적이 있어서 첫째 연을 골랐어.」","mis":"K5-2-u1-X03"},{"t":"「발자국에 빗댄 말이 새로워서 마지막 연을 골랐어.」","mis":"K5-2-u1-X09"}],"explanation":["경험과 이어진 좋은 까닭이에요.","표현을 까닭으로 들었어요.","내 경험이 떠오른 것도 까닭이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
('g5_2_kor_u1_L02_basic#7','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C10',2,'mc','auto','「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X01','K5-2-u1-X11']::text[],false,'{"seq":7,"concept":"K5-2-u1-C10","difficulty":2,"kind":"mc","stem":"「말의 온도」에서 시 전체를 읽고 느낀 것을 인상적인 부분으로 말한 것은 어느 것인가요?","options":[{"t":"「말을 조심하자고 다정하게 타이르는 듯한 분위기가 좋아.」","correct":true},{"t":"「〈발그레〉라는 낱말이 어려워서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「셋째 연이 가장 길어서 골랐어.」","mis":"K5-2-u1-X01"},{"t":"「제목에 온도가 들어가서 날씨 시인 줄 알았어.」","mis":"K5-2-u1-X11"}],"explanation":["어려운 낱말이 까닭이 아니에요.","길이는 까닭이 아니에요.","분위기도 인상적인 부분이 돼요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
('g5_2_kor_u1_L02_basic#8','kor',5,2,'u1','L02','g5_2_kor_u1_L02_basic','lesson_basic','K5-2-u1-C12',2,'mc','auto','「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":8,"concept":"K5-2-u1-C12","difficulty":2,"kind":"mc","stem":"「마음이 따끔따끔」의 느낌을 살려 낭송하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「따끔따끔」을 짧게 끊어 또렷하게 읽는다","correct":true},{"t":"모든 행을 같은 빠르기로 크게 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 작은 소리로 웅얼거린다","mis":"K5-2-u1-X10"},{"t":"「따끔따끔」만 빼고 읽는다","mis":"K5-2-u1-X10"}],"explanation":["같은 소리로만 읽으면 느낌이 안 살아요.","들리지 않으면 느낌도 안 전해져요.","찔리는 느낌을 소리로 살려요."],"asset":{"type":"passage","lines":["따뜻한 말 들으면 / 두 볼이 발그레","차가운 말 들으면 / 어깨가 움츠러들고","뾰족한 말 들으면 / 마음이 따끔따끔","말은 마음에 찍히는 발자국 / 사뿐사뿐 디뎌야 해"],"title":"시 「말의 온도」"}}'::jsonb),
