('g5_2_kor_u1_L04_challenge#1','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C15',2,'mc','auto','「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X14','K5-2-u1-X06']::text[],false,'{"seq":1,"concept":"K5-2-u1-C15","difficulty":2,"kind":"mc","stem":"「괜찮아, 나」에서 말하는 이의 행동이 어떻게 달라졌는지 바르게 말한 것은 어느 것인가요?","options":[{"t":"지우개를 박박 문지르다가, 손바닥으로 종이를 펴며 스스로를 달랜다","correct":true},{"t":"처음부터 끝까지 지우개만 문지른다","mis":"K5-2-u1-X14"},{"t":"종이를 펴다가 다시 찢어 버린다","mis":"K5-2-u1-X14"},{"t":"친구에게 새 종이를 빌린다","mis":"K5-2-u1-X06"}],"explanation":["행동이 바뀌어요.","찢어 버리지 않았어요.","친구 이야기는 없어요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb),
('g5_2_kor_u1_L04_challenge#2','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',2,'mc','auto','같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":2,"kind":"mc","stem":"같은 시에서 친구마다 까닭이 다른 이유가 아닌 것은 어느 것인가요?","options":[{"t":"한 사람만 시를 바르게 읽었기 때문에","correct":true},{"t":"겪어 본 일이 달라서","mis":"K5-2-u1-X15"},{"t":"관심 있는 것이 달라서","mis":"K5-2-u1-X15"},{"t":"알고 있는 배경지식이 달라서","mis":"K5-2-u1-X15"}],"explanation":["경험이 다르면 까닭도 달라요.","관심이 다르면 눈길이 가는 곳도 달라요.","바르게 읽은 사람이 한 명뿐인 게 아니에요."]}'::jsonb),
('g5_2_kor_u1_L04_challenge#3','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',3,'error','auto','다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X15','K5-2-u1-X03']::text[],false,'{"seq":3,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"다인이와 로운이처럼 모둠에서 의견을 나누었어요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「내 생각과 다르니까 네 말은 들을 필요가 없어.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네가 고른 부분은 나와 다르지만, 그 까닭을 들으니 새롭게 보여.」","mis":"K5-2-u1-X15"},{"t":"「너는 왜 그 연을 골랐는지 끝까지 들어 볼게.」","mis":"K5-2-u1-X03"}],"explanation":["다른 의견에서 배웠어요.","끝까지 들으려 해요.","다른 의견을 끝까지 듣고 견줘요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb),
('g5_2_kor_u1_L04_challenge#4','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C13',3,'mc','auto','공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X12']::text[],false,'{"seq":4,"concept":"K5-2-u1-C13","difficulty":3,"kind":"mc","stem":"공감하며 읽은 시를 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「이 시는 이사 간 친구를 그리워하는 시야. 나도 친한 친구가 전학 가서 같은 마음이었어.」","correct":true},{"t":"「이 시는 짧아서 좋아.」","mis":"K5-2-u1-X03"},{"t":"「나는 이사를 가 본 적이 없어서 이 시에 공감할 수 없어.」","mis":"K5-2-u1-X12"},{"t":"「이 시는 우리 반에서 나만 읽었어.」","mis":"K5-2-u1-X03"}],"explanation":["짧다는 건 공감의 까닭이 아니에요.","똑같은 일이 아니어도 비슷한 마음이면 공감해요.","어떤 시인지와 공감한 까닭을 함께 말해요."]}'::jsonb),
('g5_2_kor_u1_L04_challenge#5','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',3,'ox','auto','「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":5,"concept":"K5-2-u1-C19","difficulty":3,"kind":"ox","stem":"「방학 마지막 날」을 읽고 친구는 이불 속 장면을, 나는 시곗바늘 장면을 그렸다면 둘 중 하나는 잘못 감상한 거예요.","answer":"X","reason_options":[{"t":"같은 시에서도 인상적인 부분은 다를 수 있고, 고른 까닭을 말하면 둘 다 의미 있는 감상이기 때문에","correct":true},{"t":"한 시에서 그릴 장면은 하나로 정해져 있기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["고른 장면은 달라도 돼요.","까닭을 말하면 돼요.","다른 그림이 생각을 넓혀 줘요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb),
('g5_2_kor_u1_L04_challenge#6','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C11',3,'mc','auto','「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X09','K5-2-u1-X14']::text[],false,'{"seq":6,"concept":"K5-2-u1-C11","difficulty":3,"kind":"mc","stem":"「해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다」에 담긴 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"방학이 끝나는 것이 아쉬워 시간을 붙잡고 싶은 마음","correct":true},{"t":"시계가 고장 나서 고치고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"지붕에 올라가고 싶은 마음","mis":"K5-2-u1-X09"},{"t":"빨리 학교에 가고 싶은 마음","mis":"K5-2-u1-X14"}],"explanation":["정말 시계를 붙잡는 게 아니에요.","지붕에 오르려는 게 아니에요.","해 지는 게 아쉬운 마음이에요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb),
('g5_2_kor_u1_L04_challenge#7','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C16',3,'mc','auto','「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10','K5-2-u1-X14']::text[],false,'{"seq":7,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「괜찮아, 나」를 모둠이 연을 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"앞의 두 연은 속상하고 빠르게, 마지막 연은 천천히 다독이듯 읽는다","correct":true},{"t":"네 연을 모두 같은 크기와 빠르기로 읽는다","mis":"K5-2-u1-X10"},{"t":"가장 목소리 큰 친구가 혼자 다 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 연을 가장 빠르게 소리친다","mis":"K5-2-u1-X14"}],"explanation":["마음이 바뀌는 곳을 살려요.","나누어 맡아 이어 읽어요.","달래는 마음과 어울리지 않아요."],"asset":{"type":"passage","lines":["틀린 글씨 지우다가 / 종이가 북 찢어졌다","괜스레 지우개만 / 박박 문지른다","내 마음도 / 찢어진 종이처럼 구겨진다","손바닥으로 종이를 펴며 / 나에게 말해 본다 — 괜찮아"],"title":"시 「괜찮아, 나」"}}'::jsonb),
('g5_2_kor_u1_L04_challenge#8','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C17',4,'essay','teacher','「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u1-C17","difficulty":4,"kind":"essay","stem":"「괜찮아, 나」에서 내가 고른 인상적인 부분과 까닭을 쓰고, 다인이나 로운이의 의견을 듣고 새롭게 알게 된 점을 쓰세요.","answer_guide":{"answer":"예: 나는 셋째 연 「내 마음도 / 찢어진 종이처럼 구겨진다」가 인상적이다. 마음을 구겨진 종이에 빗대어 속상함이 눈에 보이는 것 같기 때문이다. 로운이의 말을 듣고 마지막 「괜찮아」가 스스로를 위로하는 말이라는 것을 알게 되어, 이 시가 속상함에서 끝나지 않고 위로로 끝나는 시라는 것을 새롭게 보았다.","scoring_points":["인상적인 부분을 골랐는가","까닭을 시와 이어 썼는가","친구 의견에서 새롭게 안 점을 썼는가"]},"explanation":["내 부분을 골라요.","까닭을 써요.","친구 말에서 넓어진 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"다인","text":"나는 「괜스레 지우개만 박박 문지른다」가 인상적이야. 속상할 때 나도 괜히 물건을 만지작거리거든."},{"who":"로운","text":"나는 마지막 「괜찮아」가 좋아. 스스로를 달래는 말이라 마음이 놓였어."},{"who":"다인","text":"그런데 로운이 말을 들으니 이 시가 위로하는 시로도 읽히네."},{"who":"로운","text":"나도 네 말을 듣고 지우개 문지르는 소리가 다시 들렸어."}]}}'::jsonb),
('g5_2_kor_u1_L04_challenge#9','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C19',4,'essay','teacher','「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u1-C19","difficulty":4,"kind":"essay","stem":"「방학 마지막 날」에서 그림으로 그리고 싶은 장면을 하나 골라, 그림에 무엇을 그릴지와 그 장면을 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 셋째 연 「나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다」를 그리겠다. 이불을 머리끝까지 덮은 아이와, 종이처럼 접힌 달력 한 장을 그리겠다. 하루를 접어 둔다는 표현이 방학을 아끼고 싶은 마음을 재미있게 보여 주고, 나도 방학 마지막 날에 일찍 자기 싫었던 적이 있어서 이 장면을 골랐다.","scoring_points":["장면을 시에서 골랐는가","그릴 모습을 썼는가","고른 까닭을 썼는가"]},"explanation":["장면을 골라요.","무엇을 그릴지 정해요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["해가 지붕에서 미끄러지면 / 시곗바늘을 살짝 붙잡고 싶다","책가방은 문 앞에서 / 나를 빤히 쳐다보고","나는 이불 속으로 숨어 / 방학 하루를 한 번 더 접어 둔다"],"title":"시 「방학 마지막 날」"}}'::jsonb),
('g5_2_kor_u1_L04_challenge#10','kor',5,2,'u1','L04','g5_2_kor_u1_L04_challenge','lesson_challenge','K5-2-u1-C18',4,'essay','teacher','친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u1-C18","difficulty":4,"kind":"essay","stem":"친구와 시에 대한 의견을 나눌 때 지켜야 할 태도 두 가지를 쓰고, 그렇게 하면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 첫째, 친구의 의견을 끝까지 듣는다. 둘째, 나와 다른 의견이라도 틀렸다고 하지 않고 그 까닭을 들어 본다. 이렇게 하면 내가 미처 생각하지 못한 부분을 알게 되어 같은 시를 새로운 관점으로 다시 볼 수 있다.","scoring_points":["태도 두 가지를 썼는가","경청과 존중이 드러나는가","좋은 점을 썼는가"]},"explanation":["듣는 태도를 떠올려요.","다른 의견을 대하는 태도를 써요.","좋은 점을 이어요."]}'::jsonb),
('g5_2_kor_u1_L07_basic#1','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'mc','auto','「전기문」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X18','K5-2-u1-X27']::text[],false,'{"seq":1,"concept":"K5-2-u1-C20","difficulty":1,"kind":"mc","stem":"「전기문」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글","correct":true},{"t":"지어낸 인물이 나오는 옛이야기","mis":"K5-2-u1-X18"},{"t":"날마다 겪은 일을 쓴 일기","mis":"K5-2-u1-X18"},{"t":"책을 읽고 평가한 글","mis":"K5-2-u1-X27"}],"explanation":["지어낸 인물이 아니에요.","일기와 달라요.","그건 서평이에요."]}'::jsonb),
('g5_2_kor_u1_L07_basic#2','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C22',1,'mc','auto','유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":2,"concept":"K5-2-u1-C22","difficulty":1,"kind":"mc","stem":"유관순이 살았던 시대의 상황으로 알맞은 것은 어느 것인가요?","options":[{"t":"일본에 나라를 빼앗긴 일제 강점기","correct":true},{"t":"나라를 처음 세운 때","mis":"K5-2-u1-X20"},{"t":"한글을 처음 만든 때","mis":"K5-2-u1-X20"},{"t":"오늘날과 똑같은 때","mis":"K5-2-u1-X20"}],"explanation":["나라를 세운 때가 아니에요.","한글은 훨씬 전에 만들었어요.","만세를 부른 까닭이 이 상황에 있어요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb),
('g5_2_kor_u1_L07_basic#3','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C20',1,'ox','auto','「유관순」은 실제로 살았던 인물의 이야기예요.',ARRAY['K5-2-u1-X18']::text[],false,'{"seq":3,"concept":"K5-2-u1-C20","difficulty":1,"kind":"ox","stem":"「유관순」은 실제로 살았던 인물의 이야기예요.","answer":"O","reason_options":[{"t":"실제 인물의 삶을 사실에 근거하여 쓴 전기문이기 때문에","correct":true},{"t":"지어낸 이야기에 나오는 인물이기 때문에","mis":"K5-2-u1-X18"}],"mis":"K5-2-u1-X18","explanation":["실제 인물이에요.","사실에 근거해요.","그래서 전기문이라고 해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb),
('g5_2_kor_u1_L07_basic#4','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',1,'mc','auto','유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":4,"concept":"K5-2-u1-C23","difficulty":1,"kind":"mc","stem":"유관순이 방학이면 고향 사람들에게 글을 가르친 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"배운 것을 나누어 사람들의 힘을 기르고 싶어서","correct":true},{"t":"방학 숙제였기 때문에","mis":"K5-2-u1-X21"},{"t":"고향이 심심해서","mis":"K5-2-u1-X21"},{"t":"글을 가르치면 돈을 받아서","mis":"K5-2-u1-X21"}],"explanation":["숙제 이야기는 없어요.","심심해서가 아니에요.","아버지의 말과 이어 생각해요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb),
('g5_2_kor_u1_L07_basic#5','kor',5,2,'u1','L07','g5_2_kor_u1_L07_basic','lesson_basic','K5-2-u1-C23',2,'match','auto','유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-2-u1-C23","difficulty":2,"kind":"match","stem":"유관순이 처한 상황과 그때 한 일을 알맞게 이으세요.","pairs":[{"l":"일본이 학교 문을 닫았을 때","r":"고향으로 돌아와 만세 운동을 준비했다"},{"l":"함께할 사람이 필요했을 때","r":"이 마을 저 마을을 다니며 부탁했다"},{"l":"붙잡혀 재판을 받을 때","r":"조금도 굽히지 않았다"}],"mis":"K5-2-u1-X21","explanation":["학교가 닫히자 고향에서 준비했어요.","사람을 모으려 다녔어요.","끝까지 뜻을 지켰어요."],"asset":{"type":"passage","lines":["일본이 학교 문을 닫자 유관순은 고향으로 돌아와 만세 운동을 준비했어요.","사촌 언니와 함께 이 마을 저 마을을 다니며 함께하자고 부탁했어요.","밤에는 가족과 태극기를 만들었어요.","1919년 4월 1일, 아우내 장터에 모인 사람들 앞에서","유관순은 「나라를 되찾아야 합니다」라고 외쳤어요.","붙잡혀 재판을 받을 때도 조금도 굽히지 않았고, 1920년 감옥에서 숨을 거두었어요."],"title":"전기문 「유관순」 ②"}}'::jsonb),
