('g5_2_kor_u1_L10_basic#5','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C29',2,'mc','auto','서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":5,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"서평에 줄거리를 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 일만 골라 차례대로 간단히 쓴다","correct":true},{"t":"처음부터 끝까지 빠짐없이 자세히 쓴다","mis":"K5-2-u1-X25"},{"t":"마지막 장면만 쓴다","mis":"K5-2-u1-X29"},{"t":"줄거리는 쓰지 않는다","mis":"K5-2-u1-X28"}],"explanation":["서평의 중심은 줄거리가 아니에요.","중요한 일을 차례대로 써요.","간단한 줄거리는 들어가요."]}'::jsonb),
('g5_2_kor_u1_L10_basic#6','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C30',2,'blank','auto','「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.',ARRAY['K5-2-u1-X28']::text[],false,'{"seq":6,"concept":"K5-2-u1-C30","difficulty":2,"kind":"blank","stem":"「수요일의 텃밭」 서평은 (     ) 친구들에게 이 책을 권했어요.","options":[{"t":"친구와 다투어 마음이 무거운","correct":true},{"t":"텃밭이 없는 학교의","mis":"K5-2-u1-X28"},{"t":"상추를 싫어하는","mis":"K5-2-u1-X28"},{"t":"책을 많이 읽은","mis":"K5-2-u1-X28"}],"explanation":["추천 대상이 달라요.","글에 없는 말이에요.","누구에게 왜 추천하는지 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb),
('g5_2_kor_u1_L10_basic#7','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C31',2,'mc','auto','「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?',ARRAY['K5-2-u1-X27']::text[],false,'{"seq":7,"concept":"K5-2-u1-C31","difficulty":2,"kind":"mc","stem":"「어떤 친구가 쓴 글」이 서평이 아니라 독서 감상문에 가까운 까닭은 무엇인가요?","options":[{"t":"느낀 점만 쓰고 책에 대한 평가와 그 까닭은 쓰지 않았기 때문에","correct":true},{"t":"글이 너무 짧기 때문에","mis":"K5-2-u1-X27"},{"t":"책 제목을 썼기 때문에","mis":"K5-2-u1-X27"},{"t":"「텃밭」이라는 낱말이 나오기 때문에","mis":"K5-2-u1-X27"}],"explanation":["길이로 가르지 않아요.","제목은 둘 다 쓸 수 있어요.","평가와 까닭이 있는지 봐요."],"asset":{"type":"passage","lines":["「수요일의 텃밭」을 읽고 나도 텃밭을 가꾸고 싶어졌다.","상추가 뽑혔을 때 내가 다 속상했다.","친구가 손을 내밀 때는 눈물이 날 뻔했다.","다 읽고 나니 마음이 따뜻해졌다."],"title":"어떤 친구가 쓴 글"}}'::jsonb),
('g5_2_kor_u1_L10_basic#8','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C32',2,'mc','auto','서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X01']::text[],false,'{"seq":8,"concept":"K5-2-u1-C32","difficulty":2,"kind":"mc","stem":"서평 「수요일의 텃밭」의 제목 「흙 묻은 손으로 맺은 약속」이 좋은 까닭은 무엇인가요?","options":[{"t":"읽을 사람의 관심을 끌고 책의 핵심 장면을 드러내서","correct":true},{"t":"책 제목과 똑같아서","mis":"K5-2-u1-X29"},{"t":"글자 수가 가장 많아서","mis":"K5-2-u1-X01"},{"t":"어려운 낱말을 써서","mis":"K5-2-u1-X01"}],"explanation":["책 제목과 달라요.","길이는 상관없어요.","핵심을 짧게 담았어요."],"asset":{"type":"passage","lines":["〔제목〕 흙 묻은 손으로 맺은 약속","「수요일의 텃밭」은 5학년 아이들이 학교 텃밭을 가꾸며 겪는 일을 그린 동화예요.","상추가 밤사이 모두 뽑히자 아이들은 서로를 의심하다가, 다시 씨앗을 심기로 마음을 모아요.","가장 인상적인 부분은 의심받던 친구가 흙 묻은 손을 내미는 장면이에요.","오해가 풀리는 순간이 생생하기 때문이에요.","친구와 다투어 마음이 무거운 친구들에게 이 책을 권해요.","다만 뒷부분이 조금 서둘러 끝나는 점은 아쉬워요."],"title":"서평 「수요일의 텃밭」 (지어낸 책)"}}'::jsonb),
('g5_2_kor_u1_L10_basic#9','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C28',2,'error','auto','서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X28','K5-2-u1-X30','K5-2-u1-X26']::text[],false,'{"seq":9,"concept":"K5-2-u1-C28","difficulty":2,"kind":"error","stem":"서평의 평가를 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「이 책은 재미있다. 끝.」","correct":true,"mis_target":"K5-2-u1-X28"},{"t":"「오해가 풀리는 장면이 생생해서 친구와 다툰 사람에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「뒷부분이 서둘러 끝나 조금 아쉽다.」","mis":"K5-2-u1-X26"}],"explanation":["까닭과 추천 대상이 있어요.","아쉬운 점도 평가예요.","까닭 없이 「재미있다」만 썼어요."]}'::jsonb),
('g5_2_kor_u1_L10_basic#10','kor',5,2,'u1','L10','g5_2_kor_u1_L10_basic','lesson_basic','K5-2-u1-C33',3,'mc','auto','서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":10,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 쓴 뒤 고쳐 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"친구와 돌려 읽고 받은 의견을 살펴 빠진 내용을 보탠다","correct":true},{"t":"한 번 썼으니 고치지 않는다","mis":"K5-2-u1-X30"},{"t":"글씨만 더 예쁘게 다시 쓴다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 늘린다","mis":"K5-2-u1-X25"}],"explanation":["고쳐 쓰면 더 좋아져요.","글씨보다 내용을 살펴요.","줄거리를 늘리는 게 아니에요."]}'::jsonb),
