('g5_2_kor_u1_review_b#8','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',1,'ox','auto','친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.',ARRAY['K5-2-u1-X16']::text[],false,'{"seq":8,"concept":"K5-2-u1-C18","difficulty":1,"kind":"ox","stem":"친구의 다른 의견을 들으면 작품을 새로운 관점으로 볼 수 있어요.","answer":"O","reason_options":[{"t":"내가 미처 생각하지 못한 부분을 알게 되기 때문에","correct":true},{"t":"다른 의견은 내 생각을 헷갈리게만 하기 때문에","mis":"K5-2-u1-X16"}],"mis":"K5-2-u1-X16","explanation":["다른 의견이 생각을 넓혀요.","헷갈리게 하는 게 아니에요.","귀 기울여 들어요."]}'::jsonb),
('g5_2_kor_u1_review_b#9','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C3',2,'error','auto','「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X03','K5-2-u1-X01','K5-2-u1-X07']::text[],false,'{"seq":9,"concept":"K5-2-u1-C3","difficulty":2,"kind":"error","stem":"「운동장 그림자」를 읽고 쓴 감상이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「넷째 연이 좋다. 그냥 좋다.」","correct":true,"mis_target":"K5-2-u1-X03"},{"t":"「첫째 연이 인상적이다. 아침 그림자가 나보다 길다는 것을 처음 알아차리게 되었다.」","mis":"K5-2-u1-X01"},{"t":"「둘째 연이 인상적이다. 그림자가 쪼그려 앉는다는 말이 귀엽다.」","mis":"K5-2-u1-X07"}],"explanation":["깨달음이 까닭이에요.","표현이 주는 느낌이 까닭이에요.","까닭이 없어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb),
('g5_2_kor_u1_review_b#10','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C8',2,'ox','auto','도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.',ARRAY['K5-2-u1-X08']::text[],false,'{"seq":10,"concept":"K5-2-u1-C8","difficulty":2,"kind":"ox","stem":"도윤이처럼 「혼자 있을 때 그림자가 친구 같았던 경험」을 까닭으로 드는 것은 알맞아요.","answer":"O","reason_options":[{"t":"시의 마지막 연과 이어지는 내 경험은 인상적인 까닭이 될 수 있기 때문에","correct":true},{"t":"내 경험은 작품 밖의 이야기라 까닭이 될 수 없기 때문에","mis":"K5-2-u1-X08"}],"mis":"K5-2-u1-X08","explanation":["공감도 까닭이에요.","시와 이어진 경험이에요.","「나도 그랬지」가 까닭이 돼요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb),
('g5_2_kor_u1_review_b#11','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C11',2,'mc','auto','「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?',ARRAY['K5-2-u1-X09']::text[],false,'{"seq":11,"concept":"K5-2-u1-C11","difficulty":2,"kind":"mc","stem":"「그림자가 먼저 집으로 달려간다」에서 그림자를 무엇처럼 나타냈나요?","options":[{"t":"먼저 뛰어가는 사람이나 친구","correct":true},{"t":"멈춰 있는 돌","mis":"K5-2-u1-X09"},{"t":"하늘의 구름","mis":"K5-2-u1-X09"},{"t":"운동장의 모래","mis":"K5-2-u1-X09"}],"explanation":["움직이는 모습이에요.","구름 이야기는 없어요.","사람처럼 나타냈어요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb),
('g5_2_kor_u1_review_b#12','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C21',2,'ox','auto','「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.',ARRAY['K5-2-u1-X19']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"ox","stem":"「세종 대왕」에 나온 혼잣말은 그날 그대로 받아 적은 말이 틀림없어요.","answer":"X","reason_options":[{"t":"전기문 속 인물의 말은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있기 때문에","correct":true},{"t":"전기문에 나온 말은 모두 그대로 받아 적은 것이기 때문에","mis":"K5-2-u1-X19"}],"mis":"K5-2-u1-X19","explanation":["「어떤 책에서는 그려요」라고 했어요.","그대로라고 단정할 수 없어요.","사실과 꾸민 부분을 가려요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_b#13','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C22',2,'mc','auto','전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?',ARRAY['K5-2-u1-X20']::text[],false,'{"seq":13,"concept":"K5-2-u1-C22","difficulty":2,"kind":"mc","stem":"전기문 속 인물이 한 일을 이해하려면 무엇을 함께 알아야 하나요?","options":[{"t":"인물이 살았던 때와 곳의 상황","correct":true},{"t":"인물의 키와 몸무게","mis":"K5-2-u1-X20"},{"t":"인물이 좋아한 색깔","mis":"K5-2-u1-X20"},{"t":"책의 쪽수","mis":"K5-2-u1-X20"}],"explanation":["행동의 까닭과 관계없어요.","행동의 까닭과 관계없어요.","시대 상황이 행동의 까닭이 돼요."]}'::jsonb),
('g5_2_kor_u1_review_b#14','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C29',2,'mc','auto','고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?',ARRAY['K5-2-u1-X25','K5-2-u1-X28','K5-2-u1-X29']::text[],false,'{"seq":14,"concept":"K5-2-u1-C29","difficulty":2,"kind":"mc","stem":"고쳐 쓴 서평 「낡은 책이 다시 숨 쉬는 곳」에서 줄거리는 어떻게 쓰였나요?","options":[{"t":"중요한 일만 골라 한 문장으로 간추렸다","correct":true},{"t":"날마다 일어난 일을 빠짐없이 썼다","mis":"K5-2-u1-X25"},{"t":"줄거리를 하나도 쓰지 않았다","mis":"K5-2-u1-X28"},{"t":"마지막 장면만 썼다","mis":"K5-2-u1-X29"}],"explanation":["첫 초안이 그랬어요.","간단한 줄거리는 있어요.","중요한 일을 차례대로 썼어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb),
