('g5_2_kor_u1_review_b#18','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C15',3,'mc','auto','「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"mc","stem":"「운동장 그림자」에서 그림자의 모습은 어떻게 바뀌나요?","options":[{"t":"길다가 → 발밑에 짧게 쪼그렸다가 → 먼저 달려간다","correct":true},{"t":"하루 종일 똑같이 길다","mis":"K5-2-u1-X14"},{"t":"짧다가 → 사라졌다가 → 다시 짧아진다","mis":"K5-2-u1-X14"},{"t":"아침부터 저녁까지 보이지 않는다","mis":"K5-2-u1-X14"}],"explanation":["하루 동안 바뀌어요.","사라지지 않아요.","연마다 따라가요."],"asset":{"type":"passage","lines":["아침 운동장에선 / 내 그림자가 나보다 길다","점심 운동장에선 / 그림자가 발밑에 쪼그려 앉고","저녁 운동장에선 / 그림자가 먼저 집으로 달려간다","나는 하루 종일 / 나를 따라다니는 친구가 있다"],"title":"시 「운동장 그림자」"}}'::jsonb),
('g5_2_kor_u1_review_b#19','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C24',3,'mc','auto','「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?',ARRAY['K5-2-u1-X22','K5-2-u1-X01']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 인상적인 부분으로 고를 만한 것을 가장 넓게 말한 것은 어느 것인가요?","options":[{"t":"백성의 어려움을 살핀 마음, 오랜 연구, 촛불 아래 장면처럼 여러 가지가 될 수 있다","correct":true},{"t":"훈민정음을 만든 한 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"첫 문장뿐이다","mis":"K5-2-u1-X22"},{"t":"임금이라는 낱말뿐이다","mis":"K5-2-u1-X01"}],"explanation":["하나만이 아니에요.","첫 문장만이 아니에요.","여러 가지가 될 수 있어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_b#20','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C32',3,'mc','auto','「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X29','K5-2-u1-X28']::text[],false,'{"seq":20,"concept":"K5-2-u1-C32","difficulty":3,"kind":"mc","stem":"「등대 아래 도서관」 서평의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「젖은 책을 말리던 손, 다시 열린 도서관」","correct":true},{"t":"「등대 아래 도서관」","mis":"K5-2-u1-X29"},{"t":"「서평」","mis":"K5-2-u1-X29"},{"t":"「재미있는 책」","mis":"K5-2-u1-X28"}],"explanation":["책 제목 그대로예요.","무엇에 대한 글인지 몰라요.","핵심 장면이 드러나요."]}'::jsonb),
('g5_2_kor_u1_review_b#21','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C18',3,'error','auto','「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-2-u1-X16','K5-2-u1-X18','K5-2-u1-X17']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"error","stem":"「운동장 그림자」를 읽고 모둠에서 나눈 말이에요. 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"「그건 시랑 상관없는 네 이야기잖아.」","correct":true,"mis_target":"K5-2-u1-X16"},{"t":"「네 경험을 들으니 마지막 연이 다르게 읽혀.」","mis":"K5-2-u1-X18"},{"t":"「나는 셋째 연을 골랐는데, 네가 고른 까닭도 들어 볼래.」","mis":"K5-2-u1-X17"}],"explanation":["친구 말에서 배웠어요.","끝까지 들으려 해요.","친구의 까닭을 듣기 전에 깎아내렸어요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb),
('g5_2_kor_u1_review_b#22','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C26',3,'mc','auto','「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?',ARRAY['K5-2-u1-X24','K5-2-u1-X21']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"mc","stem":"「세종 대왕」에서 본받을 점을 오늘의 나와 바르게 이은 것은 어느 것인가요?","options":[{"t":"어려워하는 친구를 위해 쉽게 설명하는 방법을 고민한다","correct":true},{"t":"옛날 임금 이야기라 나와는 관계없다","mis":"K5-2-u1-X24"},{"t":"글자를 새로 만들어 친구들에게 쓰라고 한다","mis":"K5-2-u1-X21"},{"t":"밤늦게 촛불을 켜고 공부한다","mis":"K5-2-u1-X21"}],"explanation":["옛이야기도 오늘과 이어져요.","흉내가 본받기는 아니에요.","장면만 따라 하면 뜻을 놓쳐요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_b#23','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C10',4,'essay','teacher','「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C10","difficulty":4,"kind":"essay","stem":"「종이비행기」의 말하는 이가 누구에게 어떤 마음으로 하는 말인지 쓰고, 시 전체의 분위기와 그렇게 느낀 까닭을 쓰세요.","answer_guide":{"answer":"예: 처음 무엇을 해 보며 실수할까 걱정하는 친구에게 응원하는 마음으로 하는 말이다. 시 전체가 다정하고 따뜻한 분위기이다. 「삐뚤어도 괜찮아」, 「빙글 돌아와도 좋아」처럼 잘못해도 괜찮다고 감싸 주는 말이 이어지고, 마지막에 「네가 접었다는 게 중요해」라고 해서 잘 날았는지보다 해 본 것을 칭찬하기 때문이다.","scoring_points":["누구에게 하는 말인지 썼는가","말하는 이의 마음을 썼는가","분위기와 까닭을 시와 이어 썼는가"]},"explanation":["「너」가 누구일지 떠올려요.","마음을 짐작해요.","분위기의 까닭을 시에서 찾아요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb),
('g5_2_kor_u1_review_b#24','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C23',4,'essay','teacher','「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C23","difficulty":4,"kind":"essay","stem":"「세종 대왕」에서 인상적인 부분을 하나 고르고, 그 무렵의 상황과 이어 인상적인 까닭을 쓴 뒤 세종 대왕에게 묻고 싶은 질문을 하나 쓰세요.","answer_guide":{"answer":"예: 학자들과 오랫동안 연구하여 훈민정음을 만든 부분이 인상적이다. 그 무렵 백성들은 한자를 몰라 억울한 일이 있어도 글로 남기지 못했는데, 임금이 그 어려움을 살펴 누구나 쓸 수 있는 글자를 만들었기 때문이다. 질문 — 「글자를 만들자고 했을 때 반대하는 사람은 없었나요? 그때 어떻게 마음을 지켰나요?」","scoring_points":["인상적인 부분을 골랐는가","시대 상황과 이어 까닭을 썼는가","인상적인 부분에서 나온 질문을 썼는가"]},"explanation":["부분을 골라요.","그 무렵 상황과 이어요.","마음을 묻는 질문을 만들어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_b#25','kor',5,2,'u1','','g5_2_kor_u1_review_b','unit_review','K5-2-u1-C4',4,'essay','teacher','시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C4","difficulty":4,"kind":"essay","stem":"시와 이야기에서 인상적인 부분을 찾을 때 살피는 것이 어떻게 다른지 쓰고, 이 단원에서 읽은 작품으로 예를 하나씩 드세요.","answer_guide":{"answer":"예: 시에서는 독특한 표현, 말하는 이의 마음, 분위기를 살핀다. 예를 들어 「말의 온도」에서는 「말은 마음에 찍히는 발자국」이라는 빗댄 표현이 인상적이다. 이야기에서는 인물이 처한 상황, 인물의 말과 행동, 사건의 흐름을 살핀다. 예를 들어 「유관순」에서는 재판에서도 굽히지 않은 행동이 나라를 빼앗긴 상황과 이어져 인상적이다.","scoring_points":["시에서 살필 것을 썼는가","이야기에서 살필 것을 썼는가","작품 예를 하나씩 들었는가"]},"explanation":["시를 떠올려요.","이야기를 떠올려요.","예를 들어요."]}'::jsonb),
('g5_2_kor_u1_review_c#1','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',1,'mc','auto','「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?',ARRAY['K5-2-u1-X04','K5-2-u1-X11']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"mc","stem":"「종이비행기」에서 「나도 실수했을 때 이런 말을 듣고 싶었어」라는 까닭과 가장 잘 어울리는 문장은 어느 것인가요?","options":[{"t":"「접는 선이 삐뚤어도 괜찮아」","correct":true},{"t":"「멀리 가도 좋고」","mis":"K5-2-u1-X04"},{"t":"「너의 비행기는 날 수 있어」","mis":"K5-2-u1-X04"},{"t":"제목 「종이비행기」","mis":"K5-2-u1-X11"}],"explanation":["실수 이야기와 이어지지 않아요.","실수 이야기와 이어지지 않아요.","실수를 감싸 주는 말이에요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb),
('g5_2_kor_u1_review_c#2','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C17',1,'mc','auto','친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":2,"concept":"K5-2-u1-C17","difficulty":1,"kind":"mc","stem":"친구마다 인상적인 부분이 다른 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"경험 · 관심사 · 배경지식이 서로 달라서","correct":true},{"t":"시를 읽는 속도가 달라서","mis":"K5-2-u1-X15"},{"t":"앉은 줄이 달라서","mis":"K5-2-u1-X15"},{"t":"한 사람만 시를 바르게 읽어서","mis":"K5-2-u1-X15"}],"explanation":["속도가 까닭이 아니에요.","앉은 곳과 관계없어요.","바르게 읽은 사람이 하나인 게 아니에요."]}'::jsonb),
