('g5_2_kor_u1_review_c#18','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C16',3,'mc','auto','「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?',ARRAY['K5-2-u1-X10']::text[],false,'{"seq":18,"concept":"K5-2-u1-C16","difficulty":3,"kind":"mc","stem":"「종이비행기」를 모둠이 나누어 낭송할 때 가장 알맞은 계획은 어느 것인가요?","options":[{"t":"마지막 줄 「네가 접었다는 게 중요해」를 모두 함께 힘주어 천천히 읽는다","correct":true},{"t":"한 사람이 모든 줄을 빠르게 읽는다","mis":"K5-2-u1-X10"},{"t":"마지막 줄만 빼고 읽는다","mis":"K5-2-u1-X10"},{"t":"모든 줄을 같은 크기로 읽는다","mis":"K5-2-u1-X10"}],"explanation":["나누어 맡아요.","하고 싶은 말이 마지막 줄에 있어요.","강약을 살려요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb),
('g5_2_kor_u1_review_c#19','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C25',3,'error','auto','「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u1-X23','K5-2-u1-X25']::text[],false,'{"seq":19,"concept":"K5-2-u1-C25","difficulty":3,"kind":"error","stem":"「유관순」을 읽고 만든 질문이에요. 인상적인 부분을 중심으로 만든 질문이 아닌 것은 어느 것인가요?","options":[{"t":"「충청남도는 어디에 있나요?」","correct":true,"mis_target":"K5-2-u1-X23"},{"t":"「사람들 앞에서 외칠 때 떨리지 않았나요?」","mis":"K5-2-u1-X25"},{"t":"「고향 사람들에게 글을 가르치며 무엇을 바랐나요?」","mis":"K5-2-u1-X25"}],"explanation":["장면에서 나온 질문이에요.","장면에서 나온 질문이에요.","인물의 마음과 관계없는 질문이에요."],"asset":{"type":"passage","lines":["1902년, 유관순은 충청남도의 작은 마을에서 태어났어요.","아버지는 「나라의 힘을 기르려면 새 학문을 배워야 한다」며","딸을 서울의 이화학당에 보냈어요.","유관순은 방학이면 고향에 내려가 우리글을 모르는 마을 사람들에게 글을 가르쳤어요.","1919년 3월 1일, 유관순도 친구들과 거리에 나가 「대한 독립 만세」를 불렀어요."],"title":"전기문 「유관순」 ①"}}'::jsonb),
('g5_2_kor_u1_review_c#20','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',3,'error','auto','「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-2-u1-X26','K5-2-u1-X30']::text[],false,'{"seq":20,"concept":"K5-2-u1-C30","difficulty":3,"kind":"error","stem":"「등대 아래 도서관」의 평가로 쓴 문장이에요. 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「완벽한 책이다. 아쉬운 점은 쓰면 안 된다.」","correct":true,"mis_target":"K5-2-u1-X26"},{"t":"「작은 일을 끝까지 해내는 마음이 잘 보여 책을 아끼는 친구에게 권한다.」","mis":"K5-2-u1-X30"},{"t":"「할머니 이야기가 더 나오지 않아 아쉽다.」","mis":"K5-2-u1-X30"}],"explanation":["까닭과 추천이 있어요.","아쉬운 점도 평가예요.","좋은 점만 쓰려 했어요."]}'::jsonb),
('g5_2_kor_u1_review_c#21','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C18',3,'mc','auto','하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X02','K5-2-u1-X15','K5-2-u1-X06']::text[],false,'{"seq":21,"concept":"K5-2-u1-C18","difficulty":3,"kind":"mc","stem":"하람이가 도윤이의 말을 끝까지 들었다면 얻을 수 있었던 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마지막 연을 외로울 때 곁을 지켜 주는 친구 이야기로 새롭게 읽게 된다","correct":true},{"t":"셋째 연이 정답이라는 확신","mis":"K5-2-u1-X02"},{"t":"도윤이가 틀렸다는 증거","mis":"K5-2-u1-X15"},{"t":"시를 다시 읽지 않아도 된다는 생각","mis":"K5-2-u1-X06"}],"explanation":["정답 연은 없어요.","틀린 사람은 없어요.","다른 의견이 생각을 넓혀요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb),
('g5_2_kor_u1_review_c#22','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C39',3,'error','auto','친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?',ARRAY['K5-2-u1-X35','K5-2-u1-X08','K5-2-u1-X01']::text[],false,'{"seq":22,"concept":"K5-2-u1-C39","difficulty":3,"kind":"error","stem":"친구들이 고른 인상적인 문장과 까닭이에요. 알맞지 않은 생각은 어느 것인가요?","options":[{"t":"「〈괜찮아〉는 너무 짧고 쉬워서 인상적인 문장이 될 수 없어.」","correct":true,"mis_target":"K5-2-u1-X35"},{"t":"「〈괜찮아〉가 속상할 때 나를 다독이던 엄마 말 같아서 골랐어.」","mis":"K5-2-u1-X08"},{"t":"「〈사뿐사뿐 디뎌야 해〉에서 말을 조심하자는 깨달음이 생겼어.」","mis":"K5-2-u1-X01"}],"explanation":["경험과 이어진 까닭이에요.","깨달음이 까닭이에요.","짧은 문장도 인상적일 수 있어요."]}'::jsonb),
('g5_2_kor_u1_review_c#23','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C8',4,'essay','teacher','하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C8","difficulty":4,"kind":"essay","stem":"하람이가 「그건 시랑 상관없는 네 이야기잖아」라고 했을 때, 도윤이 편에서 해 줄 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도윤이가 고른 마지막 연은 「하루 종일 / 나를 따라다니는 친구가 있다」이다. 혼자 있을 때 그림자가 친구 같았던 경험은 바로 이 연의 내용과 이어진다. 시 속 일과 닮은 내 경험이 떠올라 공감하는 것도 인상적인 까닭이 될 수 있으니, 도윤이의 까닭도 들어 볼 만하다.","scoring_points":["도윤이가 고른 연을 짚었는가","경험이 시와 이어짐을 썼는가","경험도 까닭이 된다는 뜻을 썼는가"]},"explanation":["도윤이가 고른 연을 봐요.","경험과 시를 이어요.","공감도 까닭임을 말해요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"나는 셋째 연이 인상적이야. 그림자가 먼저 집으로 달려간다니 재미있어."},{"who":"도윤","text":"나는 마지막 연! 혼자 있을 때도 그림자가 친구 같았던 적이 있거든."},{"who":"하람","text":"뭐야, 그건 시랑 상관없는 네 이야기잖아."},{"who":"도윤","text":"내 경험이 떠올라서 고른 거야. 그것도 까닭이 되지 않을까?"}]}}'::jsonb),
('g5_2_kor_u1_review_c#24','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C30',4,'essay','teacher','「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C30","difficulty":4,"kind":"essay","stem":"「낡은 책이 다시 숨 쉬는 곳」을 읽고 이 서평의 좋은 점 한 가지와 더 보태면 좋을 점 한 가지를 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 점 — 인상적인 부분으로 젖은 책을 말리는 장면을 고르고, 작은 일을 끝까지 해내는 마음이 보인다는 까닭을 들어 읽는 사람도 그 장면이 궁금해진다. 보탤 점 — 지은이와 이 책이 어떤 독자를 위한 책인지 책 소개에 더 넣으면 좋겠다. 책을 고를 때 누가 읽기 좋은지 미리 알 수 있기 때문이다.","scoring_points":["좋은 점을 까닭과 함께 썼는가","보탤 점을 까닭과 함께 썼는가","서평에 들어갈 내용과 이어 썼는가"]},"explanation":["잘된 칸을 찾아요.","빠진 칸을 찾아요.","까닭을 붙여요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb),
('g5_2_kor_u1_review_c#25','kor',5,2,'u1','','g5_2_kor_u1_review_c','unit_review','K5-2-u1-C31',4,'essay','teacher','독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C31","difficulty":4,"kind":"essay","stem":"독서 감상문과 서평의 차이를 쓰고, 친구에게 책을 추천하려면 어느 글이 더 알맞은지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다. 친구에게 책을 추천하려면 서평이 더 알맞다. 서평에는 누구에게 왜 이 책을 권하는지가 들어 있어 친구가 읽을지 말지 판단하기 쉽기 때문이다.","scoring_points":["두 글의 차이를 썼는가","어느 글이 알맞은지 골랐는가","까닭을 썼는가"]},"explanation":["두 글을 견줘요.","추천에 맞는 글을 골라요.","까닭을 써요."]}'::jsonb),
('g5_2_kor_u1_review_d#1','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',1,'blank','auto','인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.',ARRAY['K5-2-u1-X35','K5-2-u1-X02']::text[],false,'{"seq":1,"concept":"K5-2-u1-C39","difficulty":1,"kind":"blank","stem":"인상적인 문장은 길고 어려운 문장이 아니라 (     ) 문장이에요.","options":[{"t":"마음이 움직이거나 깨달음이 생긴","correct":true},{"t":"어려운 낱말이 가장 많은","mis":"K5-2-u1-X35"},{"t":"책에서 가장 긴","mis":"K5-2-u1-X35"},{"t":"선생님이 밑줄 그어 준","mis":"K5-2-u1-X02"}],"explanation":["낱말의 어려움이 기준이 아니에요.","길이가 기준이 아니에요.","정해 준 문장이 따로 있지 않아요."]}'::jsonb),
('g5_2_kor_u1_review_d#2','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C2',1,'ox','auto','작품의 인상적인 부분은 사람마다 다를 수 있어요.',ARRAY['K5-2-u1-X02']::text[],false,'{"seq":2,"concept":"K5-2-u1-C2","difficulty":1,"kind":"ox","stem":"작품의 인상적인 부분은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"같은 작품도 저마다의 경험과 생각에 따라 마음에 남는 곳이 다르기 때문에","correct":true},{"t":"작품마다 정답인 부분이 하나씩 있기 때문에","mis":"K5-2-u1-X02"}],"mis":"K5-2-u1-X02","explanation":["사람마다 달라요.","정답이 하나가 아니에요.","그래서 의견을 나눠요."]}'::jsonb),
