('g5_2_kor_u1_review_d#6','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C27',1,'mc','auto','서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?',ARRAY['K5-2-u1-X25','K5-2-u1-X29']::text[],false,'{"seq":6,"concept":"K5-2-u1-C27","difficulty":1,"kind":"mc","stem":"서평 「낡은 책이 다시 숨 쉬는 곳」에서 평가가 드러난 문장은 어느 것인가요?","options":[{"t":"「할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요.」","correct":true},{"t":"「바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.」","mis":"K5-2-u1-X25"},{"t":"「친구들과 도서관을 다시 열어요.」","mis":"K5-2-u1-X25"},{"t":"제목 「낡은 책이 다시 숨 쉬는 곳」","mis":"K5-2-u1-X29"}],"explanation":["책 소개예요.","줄거리예요.","아쉬운 점과 까닭이 있어요."],"asset":{"type":"passage","lines":["〔제목〕 낡은 책이 다시 숨 쉬는 곳","「등대 아래 도서관」은 바닷가 마을 아이가 등대 아래 낡은 도서관을 지키는 이야기예요.","해솔이는 사서 할머니에게 찢어진 책을 고치는 법을 배우고, 친구들과 도서관을 다시 열어요.","가장 인상적인 부분은 해솔이가 젖은 책을 한 장씩 말리는 장면이에요.","작은 일을 끝까지 해내는 마음이 잘 보이기 때문이에요.","책을 아끼는 마음을 기르고 싶은 친구들에게 권해요.","다만 할머니가 왜 혼자 도서관을 지켰는지가 나오지 않아 조금 아쉬워요."],"title":"서평 고쳐 쓴 글 「등대 아래 도서관」 (지어낸 책)"}}'::jsonb),
