('g5_2_kor_u1_review_d#12','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C21',2,'error','auto','「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u1-X19','K5-2-u1-X18','K5-2-u1-X21']::text[],false,'{"seq":12,"concept":"K5-2-u1-C21","difficulty":2,"kind":"error","stem":"「세종 대왕」을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「혼잣말 장면은 누가 옆에서 받아 적은 거니까 사실이야.」","correct":true,"mis_target":"K5-2-u1-X19"},{"t":"「훈민정음을 만든 것은 역사적 사실이야.」","mis":"K5-2-u1-X18"},{"t":"「촛불 장면은 작가가 그때 마음을 상상해 그린 것 같아.」","mis":"K5-2-u1-X21"}],"explanation":["사실을 바르게 말했어요.","꾸민 부분을 알아봤어요.","꾸민 장면을 사실로 단정했어요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_d#13','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C23',2,'mc','auto','「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?',ARRAY['K5-2-u1-X21']::text[],false,'{"seq":13,"concept":"K5-2-u1-C23","difficulty":2,"kind":"mc","stem":"「밤늦도록 촛불 아래에서 글자를 다듬었다」는 장면에서 짐작할 수 있는 마음은 어느 것인가요?","options":[{"t":"백성을 위해 쉬운 글자를 꼭 만들고 싶은 마음","correct":true},{"t":"잠이 오지 않아 심심한 마음","mis":"K5-2-u1-X21"},{"t":"촛불을 아끼고 싶은 마음","mis":"K5-2-u1-X21"},{"t":"학자들을 혼내고 싶은 마음","mis":"K5-2-u1-X21"}],"explanation":["백성의 어려움과 이어 봐요.","촛불이 중심이 아니에요.","상황과 행동을 이어 짐작해요."],"asset":{"type":"passage","lines":["세종 대왕은 조선의 넷째 임금이에요.","그 무렵 백성들은 어려운 한자를 몰라 하고 싶은 말을 글로 남기지 못했어요.","세종 대왕은 학자들과 함께 오랫동안 연구하여 우리글 훈민정음을 만들었어요.","어떤 책에서는 세종 대왕이 밤늦도록 촛불 아래에서 글자를 다듬으며","「백성이 쉽게 익혀 날마다 편히 쓰면 좋겠구나」라고 혼잣말을 했다고 그려요."],"title":"짧은 전기문 「세종 대왕」"}}'::jsonb),
('g5_2_kor_u1_review_d#14','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C28',2,'blank','auto','서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.',ARRAY['K5-2-u1-X25']::text[],false,'{"seq":14,"concept":"K5-2-u1-C28","difficulty":2,"kind":"blank","stem":"서평에 들어갈 내용은 제목, 책 소개, 줄거리, 인상적인 부분과 그 까닭, (     )예요.","options":[{"t":"책에 대한 평가","correct":true},{"t":"책의 값","mis":"K5-2-u1-X25"},{"t":"지은이의 사진","mis":"K5-2-u1-X25"},{"t":"다 읽은 날짜","mis":"K5-2-u1-X25"}],"explanation":["값은 들어가지 않아요.","사진은 들어가지 않아요.","좋은 점 · 아쉬운 점 · 추천을 써요."]}'::jsonb),
('g5_2_kor_u1_review_d#15','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C37',2,'mc','auto','「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u1-X33']::text[],false,'{"seq":15,"concept":"K5-2-u1-C37","difficulty":2,"kind":"mc","stem":"「이달의 책」으로 뽑히지 않은 책을 대하는 태도로 알맞은 것은 어느 것인가요?","options":[{"t":"다음 달 후보로 남기고 목록을 함께 나눈다","correct":true},{"t":"나쁜 책이라고 알린다","mis":"K5-2-u1-X33"},{"t":"추천한 친구의 의견은 쓸모없었다고 한다","mis":"K5-2-u1-X33"},{"t":"다시는 말하지 않는다","mis":"K5-2-u1-X33"}],"explanation":["뽑히지 않았다고 나쁜 책이 아니에요.","추천 까닭도 쓸모가 있어요.","다양한 의견을 인정해요."]}'::jsonb),
('g5_2_kor_u1_review_d#16','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C40',2,'error','auto','낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?',ARRAY['K5-2-u1-X36']::text[],false,'{"seq":16,"concept":"K5-2-u1-C40","difficulty":2,"kind":"error","stem":"낱말을 쓴 문장이에요. 알맞지 않은 문장은 어느 것인가요?","options":[{"t":"「간식을 모둠마다 고르게 분석했다.」","correct":true,"mis_target":"K5-2-u1-X36"},{"t":"「모은 자료를 시대별로 분류했다.」","mis":"K5-2-u1-X36"},{"t":"「이야기 속 인물의 성격을 분석했다.」","mis":"K5-2-u1-X36"}],"explanation":["바르게 썼어요.","바르게 썼어요.","나누어 주는 일은 「분배하다」예요."]}'::jsonb),
('g5_2_kor_u1_review_d#17','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C10',3,'ox','auto','「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.',ARRAY['K5-2-u1-X07']::text[],false,'{"seq":17,"concept":"K5-2-u1-C10","difficulty":3,"kind":"ox","stem":"「종이비행기」에서는 한 구절이 아니라 시 전체의 다정한 분위기를 인상적인 부분으로 말할 수 있어요.","answer":"O","reason_options":[{"t":"말하는 이의 마음이나 시 전체의 분위기도 인상적인 부분이 되기 때문에","correct":true},{"t":"인상적인 부분은 한 구절에서만 골라야 하기 때문에","mis":"K5-2-u1-X07"}],"mis":"K5-2-u1-X07","explanation":["분위기도 돼요.","구절에만 머물지 않아요.","시 전체에서 느낀 것도 돼요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb),
('g5_2_kor_u1_review_d#18','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C15',3,'ox','auto','「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.',ARRAY['K5-2-u1-X14']::text[],false,'{"seq":18,"concept":"K5-2-u1-C15","difficulty":3,"kind":"ox","stem":"「괜찮아, 나」와 「운동장 그림자」처럼 시 속 모습이나 마음은 연마다 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"연을 따라 읽으면 마음이나 모습이 어떻게 바뀌는지 보이기 때문에","correct":true},{"t":"시는 처음 연에서 모든 것이 정해지기 때문에","mis":"K5-2-u1-X14"}],"mis":"K5-2-u1-X14","explanation":["연마다 따라가요.","처음 연이 다가 아니에요.","흐름을 보며 읽어요."]}'::jsonb),
('g5_2_kor_u1_review_d#19','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C24',3,'ox','auto','이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.',ARRAY['K5-2-u1-X22']::text[],false,'{"seq":19,"concept":"K5-2-u1-C24","difficulty":3,"kind":"ox","stem":"이야기에서는 사건의 흐름이나 인물의 변화도 인상적인 부분이 될 수 있어요.","answer":"O","reason_options":[{"t":"이야기는 인물 · 사건 · 때와 곳이 작품을 이해하는 데 영향을 주기 때문에","correct":true},{"t":"이야기에서는 가장 큰 사건 한 장면만 인상적이기 때문에","mis":"K5-2-u1-X22"}],"mis":"K5-2-u1-X22","explanation":["흐름도 돼요.","변화도 돼요.","여러 가지를 살펴요."]}'::jsonb),
('g5_2_kor_u1_review_d#20','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C33',3,'mc','auto','서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?',ARRAY['K5-2-u1-X30','K5-2-u1-X25']::text[],false,'{"seq":20,"concept":"K5-2-u1-C33","difficulty":3,"kind":"mc","stem":"서평을 돌려 읽은 친구가 「인상적인 부분은 있는데 왜 인상적인지가 없어」라고 했을 때 고쳐 쓰는 방법은 어느 것인가요?","options":[{"t":"그 장면이 왜 마음에 남았는지 까닭을 한 문장 보탠다","correct":true},{"t":"인상적인 부분을 지운다","mis":"K5-2-u1-X30"},{"t":"줄거리를 더 길게 쓴다","mis":"K5-2-u1-X25"},{"t":"친구 의견은 듣지 않고 그대로 둔다","mis":"K5-2-u1-X30"}],"explanation":["지우면 중심이 빠져요.","줄거리가 문제가 아니에요.","받은 의견을 살려요."]}'::jsonb),
('g5_2_kor_u1_review_d#21','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C17',3,'ox','auto','배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.',ARRAY['K5-2-u1-X15']::text[],false,'{"seq":21,"concept":"K5-2-u1-C17","difficulty":3,"kind":"ox","stem":"배경지식이 다르면 같은 시에서도 인상적인 까닭이 달라질 수 있어요.","answer":"O","reason_options":[{"t":"아는 것이 다르면 같은 표현에서도 떠오르는 생각이 다르기 때문에","correct":true},{"t":"배경지식은 시 감상과 관계없기 때문에","mis":"K5-2-u1-X15"}],"mis":"K5-2-u1-X15","explanation":["아는 것이 생각을 바꿔요.","경험 · 관심사 · 배경지식","그래서 서로 나눠요."]}'::jsonb),
('g5_2_kor_u1_review_d#22','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C26',3,'ox','auto','오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.',ARRAY['K5-2-u1-X24']::text[],false,'{"seq":22,"concept":"K5-2-u1-C26","difficulty":3,"kind":"ox","stem":"오래전 인물의 전기문도 오늘 나의 생활에 도움을 줄 수 있어요.","answer":"O","reason_options":[{"t":"인물의 삶에서 본받을 점을 찾아 지금의 삶과 이어 볼 수 있기 때문에","correct":true},{"t":"옛날 인물은 지금과 사는 모습이 달라 배울 것이 없기 때문에","mis":"K5-2-u1-X24"}],"mis":"K5-2-u1-X24","explanation":["본받을 점을 찾아요.","오늘과 이어요.","시대가 달라도 배울 게 있어요."]}'::jsonb),
('g5_2_kor_u1_review_d#23','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C39',4,'essay','teacher','「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u1-C39","difficulty":4,"kind":"essay","stem":"「종이비행기」나 이 단원에서 읽은 시에서 가장 인상적인 문장 하나를 골라, 내 경험과 이어 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「네가 접었다는 게 중요해」가 가장 인상적이다. 미술 시간에 만든 작품이 친구 것보다 못나 보여 속상했을 때, 선생님이 끝까지 만든 것이 멋지다고 해 주셔서 힘이 났던 일이 떠올랐다. 잘하고 못하고보다 해 보는 것이 중요하다는 깨달음을 주어서 이 문장을 골랐다.","scoring_points":["문장을 골랐는가","내 경험을 썼는가","경험과 문장을 이어 까닭을 썼는가"]},"explanation":["한 문장을 골라요.","떠오른 경험을 써요.","둘을 이어요."],"asset":{"type":"passage","lines":["접는 선이 삐뚤어도 괜찮아","처음 접은 한 줄만 기억하면","너의 비행기는 날 수 있어","멀리 가도 좋고 / 빙글 돌아와도 좋아","네가 접었다는 게 중요해"],"title":"시 「종이비행기」"}}'::jsonb),
('g5_2_kor_u1_review_d#24','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C36',4,'essay','teacher','모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u1-C36","difficulty":4,"kind":"essay","stem":"모둠에서 「이달의 책」을 고르다 의견이 갈렸어요. 기준을 하나 세워 쓰고, 그 기준으로 조정하는 과정과 뽑히지 않은 책을 대하는 방법을 쓰세요.","answer_guide":{"answer":"예: 기준 — 「반 친구들 모두가 흥미롭게 읽을 수 있는가」. 먼저 친구들의 추천 까닭을 끝까지 듣고, 각 책을 이 기준에 대어 견준다. 누구나 읽기 쉽고 이야기 나눌 거리가 많은 책을 고른다. 뽑히지 않은 책은 목록에 적어 다음 달 후보로 남기고, 추천한 친구 덕분에 새 책을 알게 되었다고 고마움을 전한다.","scoring_points":["기준을 세웠는가","기준에 대어 조정하는 과정을 썼는가","뽑히지 않은 책을 존중하는 방법을 썼는가"]},"explanation":["기준을 정해요.","대어 견줘요.","다른 의견을 존중해요."]}'::jsonb),
('g5_2_kor_u1_review_d#25','kor',5,2,'u1','','g5_2_kor_u1_review_d','unit_review','K5-2-u1-C5',4,'essay','teacher','이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u1-C5","difficulty":4,"kind":"essay","stem":"이 단원에서 한 활동(시 · 이야기 · 서평 · 「이달의 책」) 가운데 가장 기억에 남는 활동 하나를 고르고, 그 활동에서 배운 점과 앞으로 책을 읽을 때 해 보고 싶은 일을 쓰세요.","answer_guide":{"answer":"예: 「이달의 책」 고르기가 가장 기억에 남는다. 내가 추천한 책은 뽑히지 않았지만, 친구들의 추천 까닭을 들으며 몰랐던 책의 좋은 점을 알게 되었고 기준을 정해 의견을 조정하는 방법을 배웠다. 앞으로 책을 읽으면 인상적인 문장과 그 까닭을 공책에 적어 두었다가 친구에게 추천할 때 써 보고 싶다.","scoring_points":["활동을 하나 골랐는가","배운 점을 썼는가","앞으로 해 보고 싶은 일을 썼는가"]},"explanation":["활동을 떠올려요.","배운 점을 써요.","다음 다짐을 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-2-u3-C1','kor',5,2,'u3',1,'지역마다 다른 인사말 — 「어서 오세요 · 어서 오슈 · 어서 오이소 · 혼저 옵서예」처럼 뜻은 같아도 지역에 따라 끝말과 말소리가 다르다',ARRAY['6국04-02 문법']::text[],1),
('K5-2-u3-C2','kor',5,2,'u3',1,'표준어의 뜻 — 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말로, 어느 지역 사람이든 함께 알아듣게 해 준다',ARRAY['6국04-02 문법']::text[],2),
('K5-2-u3-C3','kor',5,2,'u3',1,'방언의 뜻 — 특정 지역에서 주로 쓰는, 표준어가 아닌 말로 도시든 시골이든 그 지역 사람들이 오랫동안 써 온 우리말이다',ARRAY['6국04-02 문법']::text[],3),
('K5-2-u3-C4','kor',5,2,'u3',1,'단원의 흐름 — 표준어와 방언의 뜻 알기 → 쓰는 상황 조사하기 → 방언의 가치 알기 → 방언이 나오는 작품 감상하기 → 방언으로 작품 만들기',ARRAY['6국04-02 문법']::text[],4),
('K5-2-u3-C5','kor',5,2,'u3',2,'방언이 생긴 까닭 — 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고 이야기할 기회가 적어 지역마다 말이 조금씩 달라졌다(지리적 특성)',ARRAY['6국04-02 문법']::text[],5),
('K5-2-u3-C6','kor',5,2,'u3',2,'표준어를 정한 까닭 — 지역마다 말이 다르면 뜻을 나누기 어려워서 사는 곳이 달라도 원활하게 이야기할 수 있도록 표준어를 정했다',ARRAY['6국04-02 문법']::text[],6),
('K5-2-u3-C7','kor',5,2,'u3',2,'표준어를 정하는 곳과 기준 — 국립국어원이 사람들이 두루 쓰는지 · 문법에 맞는지 · 발음하기 편하고 자연스러운지를 살펴 정한다',ARRAY['6국04-02 문법']::text[],7),
('K5-2-u3-C8','kor',5,2,'u3',2,'방언이 표준어가 되기도 해요 — 「멍게」처럼 방언이 표준어보다 더 널리 쓰이게 되면 표준어로 인정되기도 하여 둘 사이는 움직이는 경계이다',ARRAY['6국04-02 문법']::text[],8),
('K5-2-u3-C9','kor',5,2,'u3',2,'한 낱말을 가리키는 여러 방언 — 개구리(까구리 · 깨고락지) · 부추(분추 · 정구지 · 소풀 · 세우리) · 김치(짐끼 · 짐치)처럼 한 낱말을 지역마다 다르게 부른다',ARRAY['6국04-02 문법']::text[],9),
('K5-2-u3-C10','kor',5,2,'u3',2,'온라인 사전으로 방언 찾기 — 국립국어원 지역어 누리집에서 표준어 낱말을 검색하면 지역별 방언과 발음을 확인할 수 있어 짐작이 아닌 근거로 찾는다',ARRAY['6국04-02 문법']::text[],10),
('K5-2-u3-C11','kor',5,2,'u3',2,'방언은 정답이 하나가 아니에요 — 방언은 같은 지역 안에서도 마을마다 다르고 지역 경계와 똑같이 나뉘지 않아, 서로 다른 답을 근거로 함께 확인한다',ARRAY['6국04-02 문법']::text[],11),
('K5-2-u3-C12','kor',5,2,'u3',4,'상황에 따라 고르는 말 — 뜻이 같은 말도 누구에게, 어떤 자리에서 말하느냐에 따라 표준어나 방언으로 골라 쓴다',ARRAY['6국04-02 문법']::text[],12),
('K5-2-u3-C13','kor',5,2,'u3',4,'표준어가 어울리는 상황 — 뉴스 · 많은 사람 앞 발표 · 학교 방송처럼 여러 지역 사람에게 공식적으로 정확히 전할 때는 주로 표준어를 쓴다',ARRAY['6국04-02 문법']::text[],13),
('K5-2-u3-C14','kor',5,2,'u3',4,'방언이 어울리는 상황 — 고향 친구와 통화 · 시장 단골손님과 대화 · 지역 축제처럼 같은 지역 사람끼리 친근함과 정을 나눌 때 방언을 쓰기도 한다',ARRAY['6국04-02 문법']::text[],14),
('K5-2-u3-C15','kor',5,2,'u3',4,'표준어로 바꾸어 보는 까닭 — 방언을 표준어로 바꾸어 보는 것은 고치기 위해서가 아니라 같은 뜻이 상황에 따라 다르게 골라 쓰인다는 것을 알기 위해서이다',ARRAY['6국04-02 문법']::text[],15),
('K5-2-u3-C16','kor',5,2,'u3',4,'사용 상황 조사의 세 가지 — 누구에게 · 어떤 상황에서 · 어떤 사이인지 살피고, 그 말을 고른 까닭까지 적어야 상황과 말의 관계가 보인다',ARRAY['6국04-02 문법']::text[],16),
('K5-2-u3-C17','kor',5,2,'u3',6,'방언에 담긴 생활 모습 — 올레(좁은 돌담길) · 정낭(대문 가로대) · 삼춘(마을 어른) · 물허벅(물동이)처럼 방언에는 그 마을의 생활과 관계가 담겨 있다',ARRAY['6국04-02 문법']::text[],17),
('K5-2-u3-C18','kor',5,2,'u3',6,'방언에 담긴 자연환경 — 감재옹심이(산이 많은 강원의 감자) · 뻘(넓은 갯벌) · 돔배기(절인 상어고기)처럼 방언에는 지역의 자연과 먹을거리가 반영된다',ARRAY['6국04-02 문법']::text[],18),
('K5-2-u3-C19','kor',5,2,'u3',6,'방언의 가치 — 방언은 지역의 자연환경과 생활 모습, 우리말의 옛 모습, 지역 사람들의 정서를 간직한 지역 문화의 자산이다',ARRAY['6국04-02 문법']::text[],19),
('K5-2-u3-C20','kor',5,2,'u3',6,'방언을 지키는 일 — 방언이 사라지면 그 말에 담긴 생활과 이야기도 잊힐 수 있어 방언 사전 · 그림책처럼 기록해 물려주려는 노력을 한다',ARRAY['6국04-02 문법']::text[],20),
('K5-2-u3-C21','kor',5,2,'u3',8,'줄거리와 인물의 마음 — 방언이 나오는 작품도 먼저 일어난 일과 인물의 마음이 어떻게 바뀌는지를 파악하며 읽는다',ARRAY['6국05-06 문학']::text[],21),
('K5-2-u3-C22','kor',5,2,'u3',8,'앞뒤 장면으로 뜻 짐작하기 — 작품 속 방언의 뜻을 모를 때는 앞뒤 장면으로 짐작하고 사전이나 지역어 누리집으로 확인한다',ARRAY['6국05-06 문학']::text[],22),
('K5-2-u3-C23','kor',5,2,'u3',8,'방언과 표준어로 읽고 느낌 견주기 — 방언을 표준어로 바꾸어도 뜻은 같지만 인물의 목소리와 분위기 같은 느낌은 달라지므로 소리 내어 읽고 견준다',ARRAY['6국05-06 문학']::text[],23),
('K5-2-u3-C24','kor',5,2,'u3',8,'작품에 방언을 쓰면 좋은 점 — 인물이 어디에 사는 누구인지 생생해지고, 인물 사이의 정과 분위기가 살아나며, 지역의 말을 기록하고 지킨다',ARRAY['6국05-06 문학']::text[],24),
('K5-2-u3-C25','kor',5,2,'u3',8,'내 삶과 이어 감상하기 — 방언을 들었던 내 경험과 작품 장면을 이어 보면 인물의 마음을 더 가깝게 느끼고 내 언어생활을 돌아볼 수 있다',ARRAY['6국05-06 문학']::text[],25),
('K5-2-u3-C26','kor',5,2,'u3',10,'방언으로 만드는 작품 — 우리 반 방언 지도 · 방언 노랫말 · 방언 상황극 가운데 고르고, 반 전체 · 모둠 · 짝 · 혼자 가운데 할 방식도 함께 정한다',ARRAY['6국04-02 문법']::text[],26),
('K5-2-u3-C27','kor',5,2,'u3',10,'방언 지도 만드는 차례 — 주제 정하기 → 모둠별 지역 나누기(고른 까닭) → 방언 · 뜻 · 생활 조사하기 → 지도에 지역명과 함께 붙이기',ARRAY['6국04-02 문법']::text[],27),
('K5-2-u3-C28','kor',5,2,'u3',10,'개수보다 뜻과 생활 — 좋은 방언 지도는 방언을 많이 모은 지도가 아니라 방언과 뜻, 그 말과 이어지는 생활이 함께 드러난 지도이다',ARRAY['6국04-02 문법']::text[],28),
('K5-2-u3-C29','kor',5,2,'u3',10,'방언을 존중하는 태도 — 방언을 흉내 내거나 웃음거리로 삼지 않고, 낯선 말도 그 지역 사람의 마음과 생활을 살려 궁금한 마음으로 대한다',ARRAY['6국04-02 문법']::text[],29),
('K5-2-u3-C30','kor',5,2,'u3',12,'함께 어우러지는 우리말 — 표준어는 원활한 의사소통을, 방언은 지역의 특성과 정서를 지켜 주므로 둘은 겨루는 말이 아니라 함께 소중한 우리말이다',ARRAY['6국04-02 문법']::text[],30),
('K5-2-u3-C31','kor',5,2,'u3',12,'상황 카드 — 까닭과 함께 고르기 — 뉴스 · 회의는 표준어, 고향 친구 · 지역 축제는 방언처럼 고르되 까닭을 함께 말하고, 표준어를 쓰는 지역이라면 표준어도 답이 된다',ARRAY['6국04-02 문법']::text[],31),
('K5-2-u3-C32','kor',5,2,'u3',12,'동형어 — 배 · 눈 · 말 · 김 · 쓰다 · 장수처럼 글자 모양은 같지만 뜻이 다른 말을 동형어라 하고, 문장의 앞뒤 말로 뜻을 가린다 (기초 다지기)',ARRAY['기초 다지기(동형어)']::text[],32)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-2-u3-X01','kor',5,'u3',ARRAY['K5-2-u3-C3']::text[],'방언은 표준어를 잘못 말한 틀린 말이라고 여긴다','오랫동안 써 온 우리말'),
('K5-2-u3-X02','kor',5,'u3',ARRAY['K5-2-u3-C1']::text[],'지역마다 인사말의 말소리가 다르면 뜻도 서로 다르다고 여긴다','뜻은 같아요'),
('K5-2-u3-X03','kor',5,'u3',ARRAY['K5-2-u3-C2','K5-2-u3-C3']::text[],'표준어는 서울 사람만 쓰는 말이고 방언은 시골에서만 쓰는 말이라고 여긴다','도시에도 방언'),
('K5-2-u3-X04','kor',5,'u3',ARRAY['K5-2-u3-C4']::text[],'단원에서 배우는 차례를 거꾸로 알거나 작품 감상부터 한다고 여긴다','뜻 → 상황 → 가치 → 작품'),
('K5-2-u3-X05','kor',5,'u3',ARRAY['K5-2-u3-C5']::text[],'방언은 옛사람들이 일부러 말을 바꾸었거나 표준어를 몰라서 생겼다고 여긴다','오가기 어려웠어요'),
('K5-2-u3-X06','kor',5,'u3',ARRAY['K5-2-u3-C6']::text[],'표준어는 방언보다 더 높고 고운 말이라서 정했다고 여긴다','함께 알아듣게'),
('K5-2-u3-X07','kor',5,'u3',ARRAY['K5-2-u3-C7']::text[],'표준어를 아무나 마음대로 정하거나 글자 수 같은 엉뚱한 기준으로 정한다고 여긴다','두루 · 문법 · 발음'),
('K5-2-u3-X08','kor',5,'u3',ARRAY['K5-2-u3-C8']::text[],'방언은 어떤 경우에도 표준어가 될 수 없다고 여긴다','멍게를 떠올려요'),
('K5-2-u3-X09','kor',5,'u3',ARRAY['K5-2-u3-C9']::text[],'한 낱말을 가리키는 방언은 하나뿐이라고 여기거나 서로 다른 방언을 다른 대상으로 여긴다','한 낱말, 여러 이름'),
('K5-2-u3-X10','kor',5,'u3',ARRAY['K5-2-u3-C10']::text[],'방언의 뜻을 근거 없이 짐작만으로 정하고 확인하지 않는다','지역어 누리집'),
('K5-2-u3-X11','kor',5,'u3',ARRAY['K5-2-u3-C11']::text[],'같은 지역이면 방언이 모두 똑같아서 다른 답은 틀렸다고 여긴다','정답은 하나가 아니에요'),
('K5-2-u3-X12','kor',5,'u3',ARRAY['K5-2-u3-C12']::text[],'같은 말을 누구에게나 어떤 자리에서나 같은 말투로 써야 한다고 여긴다','누구에게 · 어디서'),
('K5-2-u3-X13','kor',5,'u3',ARRAY['K5-2-u3-C13']::text[],'여러 지역 사람에게 전하는 방송이나 발표에서도 방언만 쓰면 똑같이 잘 전해진다고 여긴다','모두가 알아듣게'),
('K5-2-u3-X14','kor',5,'u3',ARRAY['K5-2-u3-C14']::text[],'방언은 쓰면 안 되는 말이라 고향 사람과도 표준어만 써야 한다고 여긴다','친근함과 정'),
('K5-2-u3-X15','kor',5,'u3',ARRAY['K5-2-u3-C15']::text[],'방언을 표준어로 바꾸어 보는 것을 틀린 말을 고치는 일로 여긴다','고치기가 아니라 선택'),
('K5-2-u3-X16','kor',5,'u3',ARRAY['K5-2-u3-C16']::text[],'사용 상황을 조사할 때 쓴 말만 적고 누구에게 · 어떤 상황 · 어떤 사이 · 고른 까닭을 빠뜨린다','세 가지 + 까닭'),
('K5-2-u3-X17','kor',5,'u3',ARRAY['K5-2-u3-C17']::text[],'방언은 말투만 다를 뿐 마을의 생활 모습은 담겨 있지 않다고 여긴다','말에 담긴 생활'),
('K5-2-u3-X18','kor',5,'u3',ARRAY['K5-2-u3-C18']::text[],'방언과 표준어를 짝짓기만 하고 지역의 자연환경 · 먹을거리와 잇지 않는다','자연과 이어요'),
('K5-2-u3-X19','kor',5,'u3',ARRAY['K5-2-u3-C19']::text[],'방언은 쓸모없는 옛말이라 소중하지 않다고 여긴다','지역 문화의 자산'),
('K5-2-u3-X20','kor',5,'u3',ARRAY['K5-2-u3-C20','K5-2-u3-C19']::text[],'방언이 사라져도 표준어가 있으니 잃는 것이 없다고 여기거나 방언을 소통을 막는 말로만 본다','함께 잊히는 것'),
('K5-2-u3-X21','kor',5,'u3',ARRAY['K5-2-u3-C21']::text[],'작품 속 방언 뜻만 맞히고 줄거리와 인물의 마음을 놓친다','일어난 일 · 마음'),
('K5-2-u3-X22','kor',5,'u3',ARRAY['K5-2-u3-C22']::text[],'모르는 방언이 나오면 건너뛰거나 앞뒤 장면을 보지 않고 아무 뜻으로 넘겨짚는다','앞뒤 장면으로'),
('K5-2-u3-X23','kor',5,'u3',ARRAY['K5-2-u3-C23']::text[],'방언을 표준어로 바꾸어 읽어도 느낌까지 똑같다고 여기거나 뜻까지 달라진다고 여긴다','뜻은 같고 느낌은 달라요'),
('K5-2-u3-X24','kor',5,'u3',ARRAY['K5-2-u3-C24']::text[],'방언이 나오는 작품은 읽기 어려우니 표준어로 쓴 글이 더 좋은 글이라고 여긴다','생동감과 정'),
('K5-2-u3-X25','kor',5,'u3',ARRAY['K5-2-u3-C25']::text[],'작품을 내 경험과 잇지 않고 근거 없는 느낌이나 작품과 관계없는 말만 한다','내 경험과 이어요'),
('K5-2-u3-X26','kor',5,'u3',ARRAY['K5-2-u3-C26']::text[],'방언으로 만들 수 있는 작품은 정해진 한 가지뿐이라고 여기거나 할 방식을 함께 정하지 않는다','지도 · 노랫말 · 상황극'),
('K5-2-u3-X27','kor',5,'u3',ARRAY['K5-2-u3-C27']::text[],'방언 지도 만드는 차례를 섞어 지도부터 꾸미고 주제는 나중에 정한다','주제가 먼저'),
('K5-2-u3-X28','kor',5,'u3',ARRAY['K5-2-u3-C28']::text[],'방언 지도는 방언을 많이 모을수록 잘 만든 것이라고 여긴다','개수보다 생활'),
('K5-2-u3-X29','kor',5,'u3',ARRAY['K5-2-u3-C29']::text[],'방언을 과장해 흉내 내거나 웃음거리로 삼아도 괜찮다고 여긴다','마음을 살려요'),
('K5-2-u3-X30','kor',5,'u3',ARRAY['K5-2-u3-C30']::text[],'표준어와 방언 가운데 어느 한쪽이 언제나 더 좋은 말이라고 여긴다','둘 다 소중'),
('K5-2-u3-X31','kor',5,'u3',ARRAY['K5-2-u3-C31']::text[],'상황을 살피지 않고 까닭 없이 고르거나 축제면 무조건 방언이라고 외운다','듣는 사람 · 목적'),
('K5-2-u3-X32','kor',5,'u3',ARRAY['K5-2-u3-C32']::text[],'동형어를 한 가지 뜻으로만 알고 앞뒤 말을 보지 않는다','앞뒤 말로 가려요')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_2_kor_u3_L01_basic#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',1,'mc','auto','휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":1,"kind":"mc","stem":"휴게소 안내판의 「어서 오이소.」와 뜻이 같은 표준어 인사말은 어느 것인가요?","options":[{"t":"어서 오세요.","correct":true},{"t":"안녕히 가세요.","mis":"K5-2-u3-X02"},{"t":"잘 먹겠습니다.","mis":"K5-2-u3-X02"},{"t":"다녀오겠습니다.","mis":"K5-2-u3-X02"}],"explanation":["헤어질 때 하는 인사예요.","밥 먹기 전 인사예요.","손님을 맞는 같은 뜻이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb),
('g5_2_kor_u3_L01_basic#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',1,'mc','auto','우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":2,"concept":"K5-2-u3-C2","difficulty":1,"kind":"mc","stem":"우리나라 사람들이 공통으로 쓸 수 있도록 정한 말을 무엇이라고 하나요?","options":[{"t":"표준어","correct":true},{"t":"방언","mis":"K5-2-u3-X03"},{"t":"외래어","mis":"K5-2-u3-X01"},{"t":"줄임말","mis":"K5-2-u3-X01"}],"explanation":["방언은 특정 지역의 말이에요.","다른 나라에서 온 말이에요.","모두가 함께 쓰도록 정한 말이에요."]}'::jsonb),
('g5_2_kor_u3_L01_basic#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'mc','auto','특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01','K5-2-u3-X29']::text[],false,'{"seq":3,"concept":"K5-2-u3-C3","difficulty":1,"kind":"mc","stem":"특정 지역에서 주로 쓰는, 표준어가 아닌 말을 무엇이라고 하나요?","options":[{"t":"방언","correct":true},{"t":"표준어","mis":"K5-2-u3-X03"},{"t":"높임말","mis":"K5-2-u3-X01"},{"t":"흉내 말","mis":"K5-2-u3-X29"}],"explanation":["표준어는 함께 쓰도록 정한 말이에요.","높이는 말이에요.","지역의 말을 방언이라고 해요."]}'::jsonb),
('g5_2_kor_u3_L01_basic#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',1,'ox','auto','방언은 표준어를 잘못 말한 틀린 말이에요.',ARRAY['K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":1,"kind":"ox","stem":"방언은 표준어를 잘못 말한 틀린 말이에요.","answer":"X","reason_options":[{"t":"그 지역 사람들이 오랫동안 써 온 우리말이기 때문에","correct":true},{"t":"표준어와 다르면 모두 틀린 말이기 때문에","mis":"K5-2-u3-X01"}],"mis":"K5-2-u3-X01","explanation":["방언도 우리말이에요.","틀린 말이 아니에요.","지역의 삶이 담긴 말이에요."]}'::jsonb),
('g5_2_kor_u3_L01_basic#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'mc','auto','시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":5,"concept":"K5-2-u3-C3","difficulty":2,"kind":"mc","stem":"시 「감재 한 바구니」에 나온 방언과 표준어를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"감재 — 감자, 옥시기 — 옥수수","correct":true},{"t":"감재 — 고추, 옥시기 — 옥수수","mis":"K5-2-u3-X10"},{"t":"감재 — 감자, 옥시기 — 감","mis":"K5-2-u3-X10"},{"t":"감재 — 감, 옥시기 — 오이","mis":"K5-2-u3-X10"}],"explanation":["시 넷째 줄을 다시 봐요.","옥시기는 키가 큰 옥수수예요.","시 넷째 줄에 나와요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb),
('g5_2_kor_u3_L01_basic#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C1',2,'mc','auto','네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":2,"kind":"mc","stem":"네 지역의 인사말을 보고 알 수 있는 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뜻은 같지만 지역에 따라 끝말과 말소리가 다르다","correct":true},{"t":"지역마다 손님을 맞는 뜻이 다르다","mis":"K5-2-u3-X02"},{"t":"서울·경기 지역 인사만 바른 말이다","mis":"K5-2-u3-X01"},{"t":"제주 지역 인사는 우리말이 아니다","mis":"K5-2-u3-X01"}],"explanation":["뜻은 모두 같아요.","모두 바른 우리말이에요.","말소리만 달라요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb),
('g5_2_kor_u3_L01_basic#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C4',2,'match','auto','이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-2-u3-C4","difficulty":2,"kind":"match","stem":"이 단원에서 배울 내용과 하는 일을 알맞게 이으세요.","pairs":[{"l":"표준어와 방언","r":"뜻과 생긴 까닭 알기"},{"l":"사용 상황","r":"누구에게 어떤 자리에서 쓰는지 조사하기"},{"l":"작품 속 방언","r":"방언이 하는 역할 감상하기"}],"mis":"K5-2-u3-X04","explanation":["뜻부터 알아요.","쓰는 자리를 조사해요.","작품에서 감상해요."]}'::jsonb),
('g5_2_kor_u3_L01_basic#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',2,'error','auto','시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X30','K5-2-u3-X03']::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":2,"kind":"error","stem":"시를 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「감재는 감자를 틀리게 쓴 말이니 고쳐 읽어야 해.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「부르는 이름은 달라도 똑같이 따끈하다는 줄이 좋아.」","mis":"K5-2-u3-X30"},{"t":"「감재와 옥시기는 강원 지역 방언이야.」","mis":"K5-2-u3-X03"}],"explanation":["시를 잘 느꼈어요.","바르게 알았어요.","방언은 틀린 말이 아니에요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb),
('g5_2_kor_u3_L01_basic#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C2',2,'mc','auto','기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?',ARRAY['K5-2-u3-X06','K5-2-u3-X14','K5-2-u3-X03']::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":2,"kind":"mc","stem":"기차역 안내 방송을 어느 지역에서든 표준어로 하는 까닭은 무엇인가요?","options":[{"t":"어느 지역 사람이든 함께 알아들을 수 있게 하려고","correct":true},{"t":"표준어가 방언보다 더 높은 말이라서","mis":"K5-2-u3-X06"},{"t":"방언은 방송에서 쓰면 안 되는 말이라서","mis":"K5-2-u3-X14"},{"t":"안내하는 사람이 모두 서울 사람이라서","mis":"K5-2-u3-X03"}],"explanation":["높고 낮은 말이 아니에요.","방언이 금지된 것은 아니에요.","모두가 알아듣게 하려는 거예요."]}'::jsonb),
('g5_2_kor_u3_L01_basic#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_basic','lesson_basic','K5-2-u3-C3',3,'mc','auto','할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X29','K5-2-u3-X19']::text[],false,'{"seq":10,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"할머니께서 「감재 쪄 놨다.」라고 하셨을 때 손녀의 행동으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「감재가 뭐예요?」 하고 궁금한 마음으로 여쭈어본다","correct":true},{"t":"틀린 말이라며 표준어로 고쳐 드린다","mis":"K5-2-u3-X01"},{"t":"말투를 흉내 내며 웃는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 못 들은 척한다","mis":"K5-2-u3-X19"}],"explanation":["방언은 틀린 말이 아니에요.","흉내는 예의가 아니에요.","모르는 것은 궁금한 마음으로 물어요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#1','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',2,'ox','auto','「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.',ARRAY['K5-2-u3-X02']::text[],false,'{"seq":1,"concept":"K5-2-u3-C1","difficulty":2,"kind":"ox","stem":"「어서 오슈.」와 「혼저 옵서예.」는 모두 손님을 반갑게 맞는 같은 뜻의 인사예요.","answer":"O","reason_options":[{"t":"지역에 따라 끝말과 말소리만 다를 뿐 뜻은 같기 때문에","correct":true},{"t":"말소리가 다르면 뜻도 달라지기 때문에","mis":"K5-2-u3-X02"}],"mis":"K5-2-u3-X02","explanation":["뜻은 같아요.","말소리만 달라요.","모두 손님을 맞는 인사예요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb),
('g5_2_kor_u3_L01_challenge#2','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',2,'mc','auto','이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?',ARRAY['K5-2-u3-X04']::text[],false,'{"seq":2,"concept":"K5-2-u3-C4","difficulty":2,"kind":"mc","stem":"이 단원에서 표준어와 방언의 뜻을 안 다음에 배우는 내용은 어느 것인가요?","options":[{"t":"표준어와 방언을 쓰는 상황 조사하기","correct":true},{"t":"우리 반 방언 지도를 맨 먼저 만들기","mis":"K5-2-u3-X04"},{"t":"문장 성분 찾기","mis":"K5-2-u3-X04"},{"t":"토론 절차 익히기","mis":"K5-2-u3-X04"}],"explanation":["방언 지도는 맨 끝이에요.","지난 단원이에요.","뜻 다음은 쓰는 상황이에요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#3','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',3,'mc','auto','표준어에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C2","difficulty":3,"kind":"mc","stem":"표준어에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 지역 사람이든 함께 알아듣도록 정한 말이다","correct":true},{"t":"서울에 사는 사람만 쓰는 말이다","mis":"K5-2-u3-X03"},{"t":"방언보다 더 고운 말이라서 정한 말이다","mis":"K5-2-u3-X06"},{"t":"시골에서는 쓰지 않는 말이다","mis":"K5-2-u3-X03"}],"explanation":["어디서나 써요.","곱고 덜 고운 말이 아니에요.","함께 알아듣게 정한 말이에요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#4','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',3,'mc','auto','「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X03','K5-2-u3-X01']::text[],false,'{"seq":4,"concept":"K5-2-u3-C3","difficulty":3,"kind":"mc","stem":"「방언은 시골에서만 쓰는 말이야.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「큰 도시에서도 그 지역에서 주로 쓰는 방언이 있어.」","correct":true},{"t":"「맞아, 도시 사람은 모두 표준어만 써.」","mis":"K5-2-u3-X03"},{"t":"「방언은 틀린 말이니 어디서도 안 써.」","mis":"K5-2-u3-X01"},{"t":"「방언은 할머니들만 쓰는 말이야.」","mis":"K5-2-u3-X03"}],"explanation":["도시에서도 방언을 써요.","방언은 틀린 말이 아니에요.","방언은 그 지역의 말이에요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#5','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'error','auto','인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X02','K5-2-u3-X12']::text[],false,'{"seq":5,"concept":"K5-2-u3-C1","difficulty":3,"kind":"error","stem":"인사말 안내판을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「어서 오세요만 바른 인사이고 나머지는 잘못된 인사야.」","correct":true,"mis_target":"K5-2-u3-X01"},{"t":"「말소리는 달라도 손님을 반기는 마음은 같아.」","mis":"K5-2-u3-X02"},{"t":"「우리 지역에서는 손님을 어떻게 맞는지 떠올려 보자.」","mis":"K5-2-u3-X12"}],"explanation":["마음은 같아요.","좋은 생각이에요.","모두 바른 우리말이에요."],"asset":{"type":"speech","turns":[{"who":"서울·경기 지역","text":"어서 오세요."},{"who":"충청 지역","text":"어서 오슈."},{"who":"경상 지역","text":"어서 오이소."},{"who":"제주 지역","text":"혼저 옵서예."}]}}'::jsonb),
('g5_2_kor_u3_L01_challenge#6','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C1',3,'mc','auto','지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X02','K5-2-u3-X05','K5-2-u3-X01']::text[],false,'{"seq":6,"concept":"K5-2-u3-C1","difficulty":3,"kind":"mc","stem":"지역마다 인사말이 조금씩 다른 까닭을 짐작한 말 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옛날에는 지역 사이를 오가기 어려워 말이 따로따로 자랐을 것이다","correct":true},{"t":"지역마다 손님을 반기는 마음이 달라서일 것이다","mis":"K5-2-u3-X02"},{"t":"한 지역 사람들이 일부러 말을 바꾸었을 것이다","mis":"K5-2-u3-X05"},{"t":"안내판을 만든 사람이 실수했을 것이다","mis":"K5-2-u3-X01"}],"explanation":["마음은 같아요.","일부러 바꾼 것이 아니에요.","오가기 어려워 달라졌어요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#7','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C29',3,'mc','auto','방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X19','K5-2-u3-X01']::text[],false,'{"seq":7,"concept":"K5-2-u3-C29","difficulty":3,"kind":"mc","stem":"방언을 처음 들었을 때의 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"궁금한 마음으로 뜻을 묻고 정다운 느낌을 말해 본다","correct":true},{"t":"말투를 과장해 따라 하며 웃음거리로 삼는다","mis":"K5-2-u3-X29"},{"t":"모르는 말이니 들을 필요가 없다고 여긴다","mis":"K5-2-u3-X19"},{"t":"틀린 말이라고 바로 지적한다","mis":"K5-2-u3-X01"}],"explanation":["흉내는 예의가 아니에요.","들어 볼 가치가 있어요.","궁금한 마음으로 들어요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#8','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C3',4,'essay','teacher','시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C3","difficulty":4,"kind":"essay","stem":"시 「감재 한 바구니」에서 방언을 모두 찾아 표준어로 바꾸어 쓰고, 방언으로 읽을 때의 느낌을 쓰세요.","answer_guide":{"answer":"예: 방언은 「감재」와 「옥시기」이고, 표준어로 바꾸면 「감자」와 「옥수수」이다. 방언으로 읽으니 할머니가 밭에서 직접 말씀해 주시는 것처럼 정답고 따뜻하게 느껴진다.","scoring_points":["방언 두 개를 찾았는가","표준어로 바르게 바꾸었는가","방언으로 읽을 때의 느낌을 썼는가"]},"explanation":["감재 · 옥시기를 찾아요.","감자 · 옥수수로 바꿔요.","느낌을 써요."],"asset":{"type":"passage","lines":["할머니가 밭에서 감재를 캐신다","「올해는 감재가 실하다.」","옆 고랑엔 옥시기가 내 키를 넘었다","감재는 감자, 옥시기는 옥수수","부르는 이름은 달라도","할머니 손에선 똑같이 따끈하다"],"title":"감재 한 바구니"}}'::jsonb),
('g5_2_kor_u3_L01_challenge#9','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C2',4,'essay','teacher','표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C2","difficulty":4,"kind":"essay","stem":"표준어와 방언의 뜻을 각각 쓰고, 두 말이 하는 일의 다른 점을 한 가지 쓰세요.","answer_guide":{"answer":"예: 표준어는 우리나라 사람들이 공통으로 쓸 수 있도록 정한 말이고, 방언은 특정 지역에서 주로 쓰는 표준어가 아닌 말이다. 표준어는 어느 지역 사람과도 뜻이 통하게 해 주고, 방언은 그 지역 사람들의 생활과 정을 담아 준다.","scoring_points":["표준어의 뜻을 썼는가","방언의 뜻을 썼는가","하는 일의 다른 점을 썼는가"]},"explanation":["함께 쓰도록 정한 말이에요.","지역에서 주로 쓰는 말이에요.","하는 일을 견주어요."]}'::jsonb),
('g5_2_kor_u3_L01_challenge#10','kor',5,2,'u3','L01','g5_2_kor_u3_L01_challenge','lesson_challenge','K5-2-u3-C4',4,'essay','teacher','이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C4","difficulty":4,"kind":"essay","stem":"이 단원에서 가장 알고 싶은 것을 하나 쓰고, 그것을 알면 내 언어생활에 어떤 도움이 될지 쓰세요.","answer_guide":{"answer":"예: 우리 할아버지께서 쓰시는 말이 어느 지역 방언인지 알고 싶다. 그것을 알면 할아버지 말씀을 더 잘 알아듣고, 친구들 앞에서는 표준어로, 가족끼리는 정다운 말로 상황에 맞게 골라 쓸 수 있을 것 같다.","scoring_points":["알고 싶은 것을 하나 썼는가","단원 내용과 이어지는가","언어생활에 주는 도움을 썼는가"]},"explanation":["알고 싶은 것을 골라요.","단원과 이어요.","도움을 써요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C5',1,'mc','auto','「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":1,"kind":"mc","stem":"「말에도 고향이 있어요」에서 방언이 생긴 까닭으로 든 것은 어느 것인가요?","options":[{"t":"산과 강이 많아 지역 사이를 오가기 어려워서","correct":true},{"t":"표준어를 외우기 귀찮아서","mis":"K5-2-u3-X05"},{"t":"한 지역 사람들이 일부러 말을 바꾸어서","mis":"K5-2-u3-X05"},{"t":"책이 많지 않아서","mis":"K5-2-u3-X05"}],"explanation":["글에 없는 까닭이에요.","일부러 바꾼 것이 아니에요.","셋째 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb),
('g5_2_kor_u3_L02_basic#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',1,'mc','auto','우리나라 표준어를 정하는 곳은 어디인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":2,"concept":"K5-2-u3-C7","difficulty":1,"kind":"mc","stem":"우리나라 표준어를 정하는 곳은 어디인가요?","options":[{"t":"국립국어원","correct":true},{"t":"각 지역 마을 회관","mis":"K5-2-u3-X07"},{"t":"방송국","mis":"K5-2-u3-X07"},{"t":"우리 학교 방송부","mis":"K5-2-u3-X07"}],"explanation":["마을 회관이 아니에요.","방송국은 표준어를 써요.","국립국어원이 정해요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',1,'mc','auto','「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X10']::text[],false,'{"seq":3,"concept":"K5-2-u3-C9","difficulty":1,"kind":"mc","stem":"「까구리」와 「깨고락지」가 가리키는 동물을 표준어로 쓰면 어느 것인가요?","options":[{"t":"개구리","correct":true},{"t":"고양이","mis":"K5-2-u3-X10"},{"t":"까치","mis":"K5-2-u3-X10"},{"t":"거북","mis":"K5-2-u3-X10"}],"explanation":["고양이는 겡이 · 고냉이예요.","새가 아니에요.","글 첫 문장에 나와요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb),
('g5_2_kor_u3_L02_basic#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',1,'ox','auto','원래 방언이었던 말이 표준어가 되기도 해요.',ARRAY['K5-2-u3-X08']::text[],false,'{"seq":4,"concept":"K5-2-u3-C8","difficulty":1,"kind":"ox","stem":"원래 방언이었던 말이 표준어가 되기도 해요.","answer":"O","reason_options":[{"t":"「멍게」처럼 표준어보다 더 널리 쓰이게 되면 표준어로 인정하기 때문에","correct":true},{"t":"방언은 어떤 경우에도 표준어가 될 수 없기 때문에","mis":"K5-2-u3-X08"}],"mis":"K5-2-u3-X08","explanation":["멍게를 떠올려요.","널리 쓰이면 인정해요.","움직이는 경계예요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C6',2,'mc','auto','표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X06','K5-2-u3-X07']::text[],false,'{"seq":5,"concept":"K5-2-u3-C6","difficulty":2,"kind":"mc","stem":"표준어를 정한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"사는 지역이 달라도 서로 원활하게 이야기할 수 있게 하려고","correct":true},{"t":"방언을 쓰지 못하게 막으려고","mis":"K5-2-u3-X14"},{"t":"서울 말이 가장 고운 말이라서","mis":"K5-2-u3-X06"},{"t":"글자 수를 줄이려고","mis":"K5-2-u3-X07"}],"explanation":["막으려는 것이 아니에요.","곱고 덜 고운 말이 아니에요.","함께 이야기하려고 정했어요."],"asset":{"type":"passage","lines":["개구리를 어떤 곳에서는 「까구리」, 어떤 곳에서는 「깨고락지」라고 불러요.","이처럼 특정 지역에서 주로 쓰는, 표준어가 아닌 말을 방언이라고 해요.","옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 그래서 지역마다 말이 조금씩 달라졌어요.","말이 다르면 서로 뜻을 나누기 어려워서, 어느 지역 사람이든 함께 쓸 수 있도록","정한 말이 표준어예요.","우리나라 표준어는 국립국어원이 사람들이 두루 쓰는지, 문법에 맞는지,","발음하기 편하고 자연스러운지를 살펴 정해요.","「멍게」처럼 한 지역의 방언이 표준어보다 더 널리 쓰여 표준어가 된 말도 있어요."],"title":"말에도 고향이 있어요"}}'::jsonb),
('g5_2_kor_u3_L02_basic#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C7',2,'mc','auto','국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?',ARRAY['K5-2-u3-X07']::text[],false,'{"seq":6,"concept":"K5-2-u3-C7","difficulty":2,"kind":"mc","stem":"국립국어원이 표준어를 정할 때 살펴보는 것이 아닌 것은 어느 것인가요?","options":[{"t":"글자 수가 가장 적은지","correct":true},{"t":"사람들이 두루 쓰는지","mis":"K5-2-u3-X07"},{"t":"문법에 맞는지","mis":"K5-2-u3-X07"},{"t":"발음하기 편하고 자연스러운지","mis":"K5-2-u3-X07"}],"explanation":["살펴보는 기준이에요.","살펴보는 기준이에요.","글자 수는 기준이 아니에요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'mc','auto','다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"다섯 고개의 정답을 표준어로 쓰면 어느 것인가요?","options":[{"t":"김치","correct":true},{"t":"부추","mis":"K5-2-u3-X09"},{"t":"감자","mis":"K5-2-u3-X09"},{"t":"고추","mis":"K5-2-u3-X10"}],"explanation":["부추는 정구지 · 소풀이에요.","감자는 감재예요.","짐끼 · 짐치는 김치예요."],"asset":{"type":"speech","turns":[{"who":"첫째 고개","text":"제주 지역에서는 「짐끼」라고 해요."},{"who":"둘째 고개","text":"강원 지역에서는 「짐치」라고 해요."},{"who":"셋째 고개","text":"반찬으로 먹고 매운맛이 나요."}]}}'::jsonb),
('g5_2_kor_u3_L02_basic#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C9',2,'match','auto','방언과 뜻이 같은 표준어를 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C9","difficulty":2,"kind":"match","stem":"방언과 뜻이 같은 표준어를 알맞게 이으세요.","pairs":[{"l":"정구지","r":"부추"},{"l":"고냉이","r":"고양이"},{"l":"까구리","r":"개구리"}],"mis":"K5-2-u3-X09","explanation":["경상 지역에서 써요.","강원 지역에서 써요.","한 낱말을 여러 이름으로 불러요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C8',2,'error','auto','「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X08','K5-2-u3-X09','K5-2-u3-X07']::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":2,"kind":"error","stem":"「멍게」에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「멍게는 방언이라서 지금도 표준어로 쓸 수 없어.」","correct":true,"mis_target":"K5-2-u3-X08"},{"t":"「원래 경상 지역 방언이었어.」","mis":"K5-2-u3-X09"},{"t":"「우렁쉥이보다 더 널리 쓰여 표준어가 되었어.」","mis":"K5-2-u3-X07"}],"explanation":["맞는 말이에요.","맞는 말이에요.","지금은 표준어예요."]}'::jsonb),
('g5_2_kor_u3_L02_basic#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_basic','lesson_basic','K5-2-u3-C10',3,'mc','auto','어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X10','K5-2-u3-X11']::text[],false,'{"seq":10,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"어떤 지역에서 「나무」를 어떻게 부르는지 정확히 알아보는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"국립국어원 지역어 누리집에서 「나무」를 검색해 본다","correct":true},{"t":"뜻이 비슷한 말을 짐작해서 적는다","mis":"K5-2-u3-X10"},{"t":"친구 한 명의 말만 듣고 정답으로 정한다","mis":"K5-2-u3-X11"},{"t":"표준어 사전에서 「나무」의 뜻만 찾는다","mis":"K5-2-u3-X10"}],"explanation":["짐작은 확인이 필요해요.","한 사람 말만으로는 부족해요.","지역별 방언이 나와요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#1','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',2,'ox','auto','옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.',ARRAY['K5-2-u3-X05']::text[],false,'{"seq":1,"concept":"K5-2-u3-C5","difficulty":2,"kind":"ox","stem":"옛날 사람들이 일부러 지역마다 다른 말을 만들어 써서 방언이 생겼어요.","answer":"X","reason_options":[{"t":"오가기 어려워 이야기할 기회가 적다 보니 말이 자연스럽게 달라졌기 때문에","correct":true},{"t":"지역끼리 서로 말이 통하지 않게 하려고 정했기 때문에","mis":"K5-2-u3-X05"}],"mis":"K5-2-u3-X05","explanation":["일부러가 아니에요.","자연스럽게 달라졌어요.","지리적 특성 때문이에요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#2','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',2,'mc','auto','「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X09','K5-2-u3-X11','K5-2-u3-X03']::text[],false,'{"seq":2,"concept":"K5-2-u3-C9","difficulty":2,"kind":"mc","stem":"「겡이」, 「고냉이」, 「궤이」를 보고 알 수 있는 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"한 낱말을 가리키는 방언이 지역마다 여러 가지일 수 있다","correct":true},{"t":"세 말은 서로 다른 동물을 가리킨다","mis":"K5-2-u3-X09"},{"t":"셋 가운데 하나만 맞는 방언이다","mis":"K5-2-u3-X11"},{"t":"세 말은 모두 표준어이다","mis":"K5-2-u3-X03"}],"explanation":["모두 고양이예요.","모두 그 지역의 방언이에요.","한 낱말, 여러 이름이에요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#3','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',3,'mc','auto','옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X05','K5-2-u3-X06']::text[],false,'{"seq":3,"concept":"K5-2-u3-C5","difficulty":3,"kind":"mc","stem":"옛날에도 지금처럼 교통과 통신이 발달했다면 방언은 어떠했을지 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지역 사이에 자주 오가 말이 지금보다 덜 달랐을 것이다","correct":true},{"t":"방언이 지금보다 훨씬 많아졌을 것이다","mis":"K5-2-u3-X05"},{"t":"표준어가 저절로 사라졌을 것이다","mis":"K5-2-u3-X06"},{"t":"교통과 말은 아무 관계가 없을 것이다","mis":"K5-2-u3-X05"}],"explanation":["오가면 말이 닮아 가요.","표준어와 관계없어요.","오가기 어려워 말이 달라졌어요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#4','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C6',3,'mc','auto','표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X19','K5-2-u3-X08','K5-2-u3-X06']::text[],false,'{"seq":4,"concept":"K5-2-u3-C6","difficulty":3,"kind":"mc","stem":"표준어가 없다면 생길 수 있는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다른 지역 사람과 공식적인 소식을 나눌 때 뜻을 잘못 알아들을 수 있다","correct":true},{"t":"모든 사람이 방언을 잊어버린다","mis":"K5-2-u3-X19"},{"t":"방언이 모두 표준어가 된다","mis":"K5-2-u3-X08"},{"t":"아무 문제도 생기지 않는다","mis":"K5-2-u3-X06"}],"explanation":["방언은 그대로예요.","방언이 다 바뀌지 않아요.","뜻을 나누기 어려워져요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#5','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C7',3,'error','auto','표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u3-X07','K5-2-u3-X06','K5-2-u3-X08']::text[],false,'{"seq":5,"concept":"K5-2-u3-C7","difficulty":3,"kind":"error","stem":"표준어를 정하는 방법에 대한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「목소리가 큰 사람들이 쓰는 말을 표준어로 정해.」","correct":true,"mis_target":"K5-2-u3-X07"},{"t":"「사람들이 두루 쓰는지 살펴.」","mis":"K5-2-u3-X06"},{"t":"「문법에 맞고 발음이 자연스러운지도 봐.」","mis":"K5-2-u3-X08"}],"explanation":["기준이 맞아요.","기준이 맞아요.","목소리 크기는 기준이 아니에요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#6','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C11',3,'mc','auto','방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['K5-2-u3-X11','K5-2-u3-X01','K5-2-u3-X10']::text[],false,'{"seq":6,"concept":"K5-2-u3-C11","difficulty":3,"kind":"mc","stem":"방언 카드에 「가새기 — 경상 지역 — 가위」라고 쓴 친구와, 경상 지역 할머니께서 가위를 다르게 말씀하신다는 친구가 있어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"같은 지역 안에서도 마을마다 다를 수 있으니 누리집 같은 근거를 함께 찾아본다","correct":true},{"t":"카드를 쓴 친구가 틀렸으니 카드를 지운다","mis":"K5-2-u3-X11"},{"t":"할머니 말씀이 틀렸다고 말씀드린다","mis":"K5-2-u3-X01"},{"t":"둘 다 방언이니 아무렇게나 적어도 된다","mis":"K5-2-u3-X10"}],"explanation":["둘 다 맞을 수 있어요.","할머니 말씀도 그 마을의 방언이에요.","근거로 함께 확인해요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#7','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C10',3,'mc','auto','방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u3-X29','K5-2-u3-X10']::text[],false,'{"seq":7,"concept":"K5-2-u3-C10","difficulty":3,"kind":"mc","stem":"방언 카드 놀이에서 친구가 표준어를 잘 맞히지 못할 때 도와주는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"표준어의 첫 글자나 초성을 알려 준다","correct":true},{"t":"맞히지 못하면 놀이에서 빼 준다","mis":"K5-2-u3-X29"},{"t":"방언을 과장해 다시 흉내 낸다","mis":"K5-2-u3-X29"},{"t":"아무 표준어나 말하게 한다","mis":"K5-2-u3-X10"}],"explanation":["함께 해야 해요.","흉내는 예의가 아니에요.","첫 글자나 초성으로 도와요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#8','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C5',4,'essay','teacher','방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-2-u3-C5","difficulty":4,"kind":"essay","stem":"방언이 생긴 까닭과 표준어를 정한 까닭을 이어서 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산과 강이 많아 지역 사이를 오가기 어려웠고, 서로 이야기할 기회가 적어 지역마다 말이 조금씩 달라져 방언이 생겼다. 그런데 말이 다르면 다른 지역 사람과 뜻을 나누기 어렵기 때문에, 어디에 살든 원활하게 이야기할 수 있도록 표준어를 정했다.","scoring_points":["방언이 생긴 까닭을 썼는가","표준어를 정한 까닭을 썼는가","두 까닭을 앞뒤로 이어 설명했는가"]},"explanation":["지리적 특성이에요.","원활한 의사소통이에요.","이어서 써요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#9','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C8',4,'essay','teacher','「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-2-u3-C8","difficulty":4,"kind":"essay","stem":"「멍게」가 표준어가 된 과정을 설명하고, 이를 보고 표준어와 방언의 관계에 대해 알 수 있는 점을 쓰세요.","answer_guide":{"answer":"예: 멍게는 원래 경상 지역 방언이었지만 표준어 「우렁쉥이」보다 더 널리 쓰이게 되어 지금은 둘 다 표준어가 되었다. 이를 보면 표준어와 방언 사이는 꽉 막힌 벽이 아니라, 사람들이 두루 쓰는 말에 따라 움직이는 경계라는 것을 알 수 있다.","scoring_points":["원래 방언이었음을 썼는가","더 널리 쓰여 표준어가 되었음을 썼는가","둘의 관계를 정리했는가"]},"explanation":["원래 지역을 써요.","널리 쓰인 것이 까닭이에요.","움직이는 경계예요."]}'::jsonb),
('g5_2_kor_u3_L02_challenge#10','kor',5,2,'u3','L02','g5_2_kor_u3_L02_challenge','lesson_challenge','K5-2-u3-C9',4,'essay','teacher','내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-2-u3-C9","difficulty":4,"kind":"essay","stem":"내가 아는 낱말로 방언 고개 문제를 만들어 쓰세요. 고개를 셋 이상 만들고, 고개마다 지역과 방언 또는 특징을 넣은 뒤 정답을 표준어로 쓰세요.","answer_guide":{"answer":"예: 첫째 고개 — 경상 지역에서는 「정구지」라고 해요. 둘째 고개 — 전라 지역에서는 「소풀」이라고 해요. 셋째 고개 — 부침개에 넣는 초록색 채소예요. 정답 — 부추.","scoring_points":["고개를 셋 이상 만들었는가","지역과 방언 또는 특징을 넣었는가","정답을 표준어로 썼는가"]},"explanation":["고개를 만들어요.","지역과 방언을 넣어요.","정답은 표준어예요."]}'::jsonb),
('g5_2_kor_u3_L04_basic#1','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C14',1,'mc','auto','「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?',ARRAY['K5-2-u3-X14','K5-2-u3-X03','K5-2-u3-X13']::text[],false,'{"seq":1,"concept":"K5-2-u3-C14","difficulty":1,"kind":"mc","stem":"「설날, 외할머니 댁에서」에서 엄마가 외삼촌과 이야기할 때 방언을 쓴 까닭은 무엇인가요?","options":[{"t":"고향 사람과 이야기하면 더 가깝게 느껴져서","correct":true},{"t":"표준어를 몰라서","mis":"K5-2-u3-X14"},{"t":"외삼촌이 표준어를 못 알아들어서","mis":"K5-2-u3-X03"},{"t":"방송에 나가야 해서","mis":"K5-2-u3-X13"}],"explanation":["엄마는 표준어도 써요.","외삼촌도 표준어를 알아요.","넷째 · 다섯째 줄에 나와요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb),
('g5_2_kor_u3_L04_basic#2','kor',5,2,'u3','L04','g5_2_kor_u3_L04_basic','lesson_basic','K5-2-u3-C13',1,'mc','auto','기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?',ARRAY['K5-2-u3-X01','K5-2-u3-X14','K5-2-u3-X06']::text[],false,'{"seq":2,"concept":"K5-2-u3-C13","difficulty":1,"kind":"mc","stem":"기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 표준어로 말한 까닭은 무엇인가요?","options":[{"t":"전국 사람에게 똑같이 정확히 전하려고","correct":true},{"t":"방언은 틀린 말이라서","mis":"K5-2-u3-X01"},{"t":"고향 사람과 가까워지려고","mis":"K5-2-u3-X14"},{"t":"표준어가 더 높은 말이라서","mis":"K5-2-u3-X06"}],"explanation":["방언은 틀린 말이 아니에요.","그건 엄마의 까닭이에요.","여러 지역 사람에게 전해요."],"asset":{"type":"passage","lines":["설날 아침, 우리 가족은 충청 지역에 있는 외할머니 댁에 갔다.","엄마는 마당에서 외삼촌을 보자마자 「오빠, 일찍 왔네유. 길 막혀서 힘들었슈?」 하고 물었다.","집에서와는 다른 엄마 말투에 나는 고개를 갸웃했다.","저녁에 엄마는 「고향 사람과 이야기하면 어릴 때 쓰던 말이 저절로 나와.","그래야 더 가깝게 느껴지거든.」 하고 웃으셨다.","그날 밤 뉴스에서는 기상 캐스터가 「내일은 전국에 눈이 내리겠습니다.」 하고 또박또박 말했다."],"title":"설날, 외할머니 댁에서"}}'::jsonb),
