('g5_2_kor_u4_L11_basic#3','kor',5,2,'u4','L11','g5_2_kor_u4_L11_basic','lesson_basic','K5-2-u4-C15',1,'mc','auto','쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X31']::text[],false,'{"seq":3,"concept":"K5-2-u4-C15","difficulty":1,"kind":"mc","stem":"쪽지를 토의 주제로 바꾼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"어떻게 하면 수돗가 바닥을 깨끗하게 쓸까?","correct":true},{"t":"수돗가가 물바다라서 정말 싫다.","mis":"K5-2-u4-X15"},{"t":"도서관은 내 탓이 아니다.","mis":"K5-2-u4-X15"},{"t":"급식실 줄은 원래 길다.","mis":"K5-2-u4-X31"}],"explanation":["불평하는 말이에요.","탓하는 말이에요.","방법을 묻는 물음이에요."],"asset":{"type":"passage","lines":["급식실 — 「줄이 너무 길어요.」","수돗가 — 「바닥이 물바다예요.」","도서관 — 「책이 제자리에 없어요.」","화장실 — 「휴지가 바닥에 떨어져 있어요.」"],"title":"우리 학교 지도에 붙은 쪽지"}}'::jsonb),
