('g5_2_kor_u4_review_a#8','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C29',1,'mc','auto','「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?',ARRAY['K5-2-u4-X29']::text[],false,'{"seq":8,"concept":"K5-2-u4-C29","difficulty":1,"kind":"mc","stem":"「소중한 것이 서로 다를 때」에서 부딪침이 생기는 까닭은 어느 것인가요?","options":[{"t":"사람마다 소중하게 여기는 것이 달라서","correct":true},{"t":"한쪽이 나쁜 사람이라서","mis":"K5-2-u4-X29"},{"t":"규칙이 하나도 없어서","mis":"K5-2-u4-X29"},{"t":"모두 같은 것을 좋아해서","mis":"K5-2-u4-X29"}],"explanation":["나쁜 사람이 아니에요.","글에 없어요.","가치가 달라서예요."],"asset":{"type":"passage","lines":["사람마다 소중하게 여기는 것이 달라요.","내가 소중히 여기는 일이 다른 사람에게 불편을 줄 때도 있어요.","공원 산책길에서 자전거를 타는 사람은 시원하게 달리고 싶고,","걷는 사람은 마음 놓고 천천히 걷고 싶어요.","저녁 늦게 놀이터에서 공을 차는 아이들은 즐겁지만,","하루 일을 마치고 쉬고 싶은 이웃은 시끄러워 잠들기 어려워요.","이처럼 소중한 것이 부딪칠 때에는 누가 옳은지 겨루기보다","서로 조금씩 양보할 방법을 함께 찾아야 해요."],"title":"소중한 것이 서로 다를 때"}}'::jsonb),
('g5_2_kor_u4_review_a#9','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C15',2,'mc','auto','「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?',ARRAY['K5-2-u4-X15','K5-2-u4-X06']::text[],false,'{"seq":9,"concept":"K5-2-u4-C15","difficulty":2,"kind":"mc","stem":"「꿈나무반 학급 토의 기록장」의 토의 주제는 어느 것인가요?","options":[{"t":"어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","correct":true},{"t":"화분은 누가 시들게 했을까?","mis":"K5-2-u4-X15"},{"t":"창가를 어떻게 넓힐까?","mis":"K5-2-u4-X06"},{"t":"이름표를 어디서 살까?","mis":"K5-2-u4-X06"}],"explanation":["탓하는 물음이에요.","주제가 아니에요.","기록장 첫 줄이에요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb),
