('g5_2_kor_u4_review_a#17','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C19',3,'mc','auto','기록장의 합의점은 세 의견을 어떻게 살렸나요?',ARRAY['K5-2-u4-X19','K5-2-u4-X10','K5-2-u4-X20']::text[],false,'{"seq":17,"concept":"K5-2-u4-C19","difficulty":3,"kind":"mc","stem":"기록장의 합의점은 세 의견을 어떻게 살렸나요?","options":[{"t":"이름표 · 당번 · 창가 의견의 장점을 모두 살리고 단점을 메웠다","correct":true},{"t":"지안이 의견만 그대로 골랐다","mis":"K5-2-u4-X19"},{"t":"로운이 의견은 단점이 있어 버렸다","mis":"K5-2-u4-X10"},{"t":"태린이 의견이 이겨서 그대로 정했다","mis":"K5-2-u4-X20"}],"explanation":["셋 다 살렸어요.","줄여서 살렸어요.","모아서 고쳤어요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb),
('g5_2_kor_u4_review_a#18','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',3,'mc','auto','블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X12','K5-2-u4-X08']::text[],false,'{"seq":18,"concept":"K5-2-u4-C11","difficulty":3,"kind":"mc","stem":"블록 토의에서 세 의견의 장점을 살린 합의점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"매트 안에서 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다","correct":true},{"t":"블록 놀이를 아예 없앤다","mis":"K5-2-u4-X30"},{"t":"하윤이 의견만 그대로 따른다","mis":"K5-2-u4-X12"},{"t":"목소리 큰 모둠이 먼저 논다","mis":"K5-2-u4-X08"}],"explanation":["모두의 바람을 지우지 않아요.","하나만 고르지 않아요.","장점을 모았어요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb),
('g5_2_kor_u4_review_a#19','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C26',3,'mc','auto','학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X26','K5-2-u4-X22']::text[],false,'{"seq":19,"concept":"K5-2-u4-C26","difficulty":3,"kind":"mc","stem":"학급 토의에서 늘 같은 친구들만 발표할 때 사회자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"의견을 마련할 시간을 주고 아직 말하지 않은 친구에게 차례를 준다","correct":true},{"t":"발표 잘하는 친구에게 계속 맡긴다","mis":"K5-2-u4-X26"},{"t":"사회자가 대신 정한다","mis":"K5-2-u4-X22"},{"t":"조용한 친구는 의견이 없다고 여긴다","mis":"K5-2-u4-X26"}],"explanation":["몇몇만 말하게 돼요.","대신 정하지 않아요.","모두 말하게 도와요."]}'::jsonb),
('g5_2_kor_u4_review_a#20','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',3,'mc','auto','산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X30','K5-2-u4-X31']::text[],false,'{"seq":20,"concept":"K5-2-u4-C30","difficulty":3,"kind":"mc","stem":"산책길 문제에서 두 사람의 가치를 모두 존중한 의견으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"가운데 선을 긋고 붐비는 저녁엔 자전거를 끌고 가자","correct":true},{"t":"자전거를 아예 못 타게 하자","mis":"K5-2-u4-X30"},{"t":"걷는 사람이 늘 비켜 주자","mis":"K5-2-u4-X30"},{"t":"아무것도 바꾸지 말자","mis":"K5-2-u4-X31"}],"explanation":["한쪽만 지켜요.","한쪽만 양보해요.","둘 다 존중해요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb),
('g5_2_kor_u4_review_a#21','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C18',3,'mc','auto','친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?',ARRAY['K5-2-u4-X18','K5-2-u4-X17']::text[],false,'{"seq":21,"concept":"K5-2-u4-C18","difficulty":3,"kind":"mc","stem":"친구 의견에 빈틈이 보일 때 가장 알맞은 말은 어느 것인가요?","options":[{"t":"「궁금해서 묻는데, 비 오는 날에는 어떻게 해?」","correct":true},{"t":"「그 의견은 빈틈투성이야.」","mis":"K5-2-u4-X18"},{"t":"「그냥 넘어가자.」","mis":"K5-2-u4-X17"},{"t":"「그럴 줄 알았어.」","mis":"K5-2-u4-X18"}],"explanation":["공격하는 말이에요.","빈틈이 남아요.","공손하게 물어요."]}'::jsonb),
('g5_2_kor_u4_review_a#22','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C38',3,'mc','auto','「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-2-u4-X38','K5-2-u4-X08']::text[],false,'{"seq":22,"concept":"K5-2-u4-C38","difficulty":3,"kind":"mc","stem":"「좋은 의견은 처음부터 정해져 있어서 찾기만 하면 된다.」라는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「서로 견주고 고치는 과정에서 처음보다 나은 의견이 만들어져.」","correct":true},{"t":"「맞아, 선생님이 정답을 알고 계셔.」","mis":"K5-2-u4-X38"},{"t":"「목소리 큰 친구 의견이 정답이야.」","mis":"K5-2-u4-X08"},{"t":"「처음 나온 의견이 늘 정답이야.」","mis":"K5-2-u4-X38"}],"explanation":["정답이 정해진 게 아니에요.","목소리로 정하지 않아요.","과정에서 나아져요."]}'::jsonb),
('g5_2_kor_u4_review_a#23','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C11',4,'essay','teacher','토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C11","difficulty":4,"kind":"essay","stem":"토의 「블록 놀이 자리」의 세 의견 가운데 둘 이상의 장점을 살려 합의점을 쓰고, 어떤 단점을 어떻게 메웠는지 쓰세요.","answer_guide":{"answer":"예: 매트 안에서 한 번에 네 명까지 놀고, 작은 목소리 규칙을 안내판으로 붙인다. 인원만 정하면 꾸준히 지키기 어렵다는 단점을 안내판으로 메웠고, 규칙만 정하면 자리가 좁다는 단점을 인원 제한으로 메웠다.","scoring_points":["둘 이상의 장점을 살렸는가","합의점을 분명히 썼는가","메운 단점을 썼는가"]},"explanation":["장점을 모아요.","합의점을 써요.","단점을 어떻게 메웠는지 써요."],"asset":{"type":"speech","turns":[{"who":"사회자","text":"쉬는 시간에 교실 뒤 블록 놀이 자리가 좁고 시끄러워서 다툼이 생깁니다. 풀 방법을 말해 봅시다."},{"who":"하윤","text":"한 번에 네 명까지만 놀면 좋겠습니다. 자리가 넉넉해지고 소리도 줄 것입니다."},{"who":"준서","text":"모둠마다 요일을 정하면 어떨까요? 서로 차례를 기다리며 양보하게 될 것입니다."},{"who":"나은","text":"놀이 자리와 규칙을 정하면 좋겠습니다. 매트 안에서만 작은 목소리로 놀기로 하면 됩니다."}]}}'::jsonb),
('g5_2_kor_u4_review_a#24','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C30',4,'essay','teacher','우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C30","difficulty":4,"kind":"essay","stem":"우리 주변에서 서로 다른 가치가 부딪치는 일을 하나 골라 두 사람이 소중히 여기는 것을 쓰고, 둘 다 존중하는 방법을 쓰세요.","answer_guide":{"answer":"예: 밤늦게 악기를 연습하고 싶은 이웃과 조용히 쉬고 싶은 이웃이 있다. 한 사람은 연주 실력을, 다른 사람은 편안한 휴식을 소중히 여긴다. 저녁 일찍까지만 연습하고 소리를 줄이는 깔개를 깔면 둘 다 존중할 수 있다.","scoring_points":["부딪치는 일을 골랐는가","두 사람의 가치를 썼는가","둘 다 존중하는 방법을 썼는가"]},"explanation":["부딪침을 골라요.","두 가치를 써요.","둘 다 존중해요."]}'::jsonb),
('g5_2_kor_u4_review_a#25','kor',5,2,'u4','','g5_2_kor_u4_review_a','unit_review','K5-2-u4-C9',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C9","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 의견 하나를 골라 검토 기준 두 가지에 비추어 장점과 단점을 쓰세요.","answer_guide":{"answer":"예: 태린이의 당번 의견은 효과적인가 기준으로 보면 날마다 잊지 않고 물을 줄 수 있다는 장점이 있다. 여러 사람에게 도움이 되는가 기준으로 보면 당번만 애쓰고 다른 친구는 신경 쓰지 않을 수 있다는 단점이 있다.","scoring_points":["의견 하나를 골랐는가","기준 두 가지를 밝혔는가","장점과 단점을 의견을 두고 썼는가"]},"explanation":["의견을 골라요.","기준을 밝혀요.","장단점을 써요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb),
