('g5_2_kor_u4_review_b#14','kor',5,2,'u4','','g5_2_kor_u4_review_b','unit_review','K5-2-u4-C36',2,'mc','auto','「당번 정하기」와 「이름표 꽂기」를 함께 살린 의견은 어떤 생각 도구로 만든 것인가요?',ARRAY['K5-2-u4-X36']::text[],false,'{"seq":14,"concept":"K5-2-u4-C36","difficulty":2,"kind":"mc","stem":"「당번 정하기」와 「이름표 꽂기」를 함께 살린 의견은 어떤 생각 도구로 만든 것인가요?","options":[{"t":"합치기","correct":true},{"t":"빼기","mis":"K5-2-u4-X36"},{"t":"순서 바꾸기","mis":"K5-2-u4-X36"},{"t":"포기하기","mis":"K5-2-u4-X36"}],"explanation":["덜어 내지 않았어요.","차례를 바꾸지 않았어요.","두 의견을 합쳤어요."],"asset":{"type":"passage","lines":["바꾸기 — 다른 것으로 바꿀 수 있을까?","합치기 — 두 의견을 합칠 수 있을까?","줄이기 · 빼기 — 일부를 줄이거나 빼면 어떨까?","순서 바꾸기 — 차례나 역할을 바꾸면 어떨까?"],"title":"합의점이 막힐 때 던지는 물음"}}'::jsonb),
