('g5_2_kor_u4_review_d#20','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C29',3,'error','auto','주변의 부딪침을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X29','K5-2-u4-X30']::text[],false,'{"seq":20,"concept":"K5-2-u4-C29","difficulty":3,"kind":"error","stem":"주변의 부딪침을 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「공원에서 자전거 타는 사람은 다 이기적이야.」","correct":true,"mis_target":"K5-2-u4-X29"},{"t":"「자전거 타는 사람은 시원하게 달리고 싶은 거야.」","mis":"K5-2-u4-X29"},{"t":"「걷는 사람은 마음 놓고 걷고 싶은 거야.」","mis":"K5-2-u4-X30"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","나쁜 사람이 아니라 가치가 달라요."],"asset":{"type":"speech","turns":[{"who":"가온","text":"주제는 「자전거와 걷는 사람이 산책길을 함께 안전하게 쓰는 방법」으로 하자. 우리 동네 공원 이야기니까."},{"who":"시우","text":"산책길에 가운데 선을 그어 자전거 길과 걷는 길을 나누면 좋겠어. 서로 부딪칠 일이 줄거든."},{"who":"다인","text":"산책하는 사람이 많은 저녁에는 자전거를 끌고 가게 하면 어때?"},{"who":"준혁","text":"자전거를 아예 못 타게 하면 어때? 걷는 사람이 가장 안전하잖아."}]}}'::jsonb),
('g5_2_kor_u4_review_d#21','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C21',3,'error','auto','모둠 토의 장면을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-2-u4-X21','K5-2-u4-X17']::text[],false,'{"seq":21,"concept":"K5-2-u4-C21","difficulty":3,"kind":"error","stem":"모둠 토의 장면을 본 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「다들 좋다고만 하니 이 토의는 완벽해.」","correct":true,"mis_target":"K5-2-u4-X21"},{"t":"「단점도 따져 봐야 실천할 때 문제가 적어.」","mis":"K5-2-u4-X21"},{"t":"「궁금한 점을 물어보면 의견이 더 단단해져.」","mis":"K5-2-u4-X17"}],"explanation":["알맞은 말이에요.","알맞은 말이에요.","맞장구만으로는 부족해요."]}'::jsonb),
('g5_2_kor_u4_review_d#22','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C3',3,'mc','auto','의견 조정과 토의의 관계를 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-2-u4-X02','K5-2-u4-X24','K5-2-u4-X01']::text[],false,'{"seq":22,"concept":"K5-2-u4-C3","difficulty":3,"kind":"mc","stem":"의견 조정과 토의의 관계를 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"토의에서 서로 다른 의견을 조정해 함께 받아들일 방법을 찾는다","correct":true},{"t":"토의에서 이긴 쪽 의견만 남긴다","mis":"K5-2-u4-X02"},{"t":"의견 조정은 토의와 관계없다","mis":"K5-2-u4-X24"},{"t":"의견이 다르면 토의를 멈춘다","mis":"K5-2-u4-X01"}],"explanation":["겨루지 않아요.","조정은 토의 안에 있어요.","함께 받아들일 방법을 찾아요."]}'::jsonb),
('g5_2_kor_u4_review_d#23','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C17',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 세 의견 가운데 하나를 골라 궁금한 점을 묻는 공손한 질문을 쓰고, 그 질문이 의견을 어떻게 다듬는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-2-u4-C17","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 세 의견 가운데 하나를 골라 궁금한 점을 묻는 공손한 질문을 쓰고, 그 질문이 의견을 어떻게 다듬는지 쓰세요.","answer_guide":{"answer":"예: 태린이의 의견에 「궁금해서 묻는데, 방학에는 누가 물을 줘?」라고 묻겠다. 이 질문에 답하려면 방학 동안 돌아가며 들르는 방법을 정해야 해서 당번 의견이 더 단단해진다.","scoring_points":["의견을 하나 골랐는가","공손한 질문을 썼는가","질문이 의견을 다듬는 점을 썼는가"]},"explanation":["의견을 골라요.","공손하게 물어요.","다듬어지는 점을 써요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb),
('g5_2_kor_u4_review_d#24','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C33',4,'essay','teacher','「꿈나무반 학급 토의 기록장」의 합의점을 실천하기 위해 누가 무엇을 언제 할지 실천 계획을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-2-u4-C33","difficulty":4,"kind":"essay","stem":"「꿈나무반 학급 토의 기록장」의 합의점을 실천하기 위해 누가 무엇을 언제 할지 실천 계획을 쓰세요.","answer_guide":{"answer":"예: 다음 주 월요일까지 모둠마다 코팅한 이름표를 만들어 화분에 꽂고, 당번 표를 교실 뒤에 붙여 날마다 차례대로 물을 준다. 해가 필요한 화분은 창가로 옮기고, 한 주가 지나면 잘되었는지 함께 되돌아본다.","scoring_points":["누가 할지 썼는가","무엇을 할지 썼는가","언제 하고 어떻게 되돌아볼지 썼는가"]},"explanation":["누가예요.","무엇을이에요.","언제와 되돌아보기예요."],"asset":{"type":"passage","lines":["주제 — 어떻게 하면 우리 반 화분을 시들지 않게 돌볼까?","태린 — 물 주는 당번을 정하자. 날마다 잊지 않고 챙길 수 있다.","지안 — 화분마다 물 주는 날을 적은 이름표를 꽂자. 누구나 보고 안다.","로운 — 화분을 모두 창가로 옮기자. 햇빛을 받으면 덜 시든다.","질문 — 「이름표는 비에 젖거나 떨어지면 어떻게 해?」","로운 의견의 단점 — 창가가 좁아 화분이 다 들어가지 않는다.","합의점 — 코팅한 이름표를 꽂고, 당번은 모두 돌아가며 맡고, 해가 필요한 화분만 창가로","되돌아보기 — 질문 덕분에 이름표 의견이 더 단단해졌다."],"title":"꿈나무반 학급 토의 기록장"}}'::jsonb),
('g5_2_kor_u4_review_d#25','kor',5,2,'u4','','g5_2_kor_u4_review_d','unit_review','K5-2-u4-C20',4,'essay','teacher','토의에서 내 의견이 뽑히지 않았던 경험이나 상황을 떠올려, 그때의 마음과 참여가 소중한 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-2-u4-C20","difficulty":4,"kind":"essay","stem":"토의에서 내 의견이 뽑히지 않았던 경험이나 상황을 떠올려, 그때의 마음과 참여가 소중한 까닭을 쓰세요.","answer_guide":{"answer":"예: 모둠 토의에서 내 의견이 뽑히지 않아 처음에는 속상했다. 그런데 내가 한 질문 덕분에 모둠 의견의 빈틈이 메워졌다. 내 의견이 그대로 뽑히지 않아도 함께 말하고 고친 과정 속에 내 생각이 들어 있어 참여한 것이 소중하다.","scoring_points":["경험이나 상황을 떠올렸는가","그때의 마음을 썼는가","참여가 소중한 까닭을 썼는가"]},"explanation":["경험을 떠올려요.","마음을 써요.","까닭을 써요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-2-u5-C1','kor',5,2,'u5',1,'글에 드러나지 않은 내용 — 글에는 모든 것이 쓰여 있지 않아, 쓰여 있지 않은 까닭이나 마음도 단서로 짐작해 볼 수 있다',ARRAY['6국02-02 읽기']::text[],1),
('K5-2-u5-C2','kor',5,2,'u5',1,'추론의 뜻 — 글에 드러나지 않은 내용을 글의 단서나 자신의 경험·지식을 바탕으로 짐작하는 것',ARRAY['6국02-02 읽기']::text[],2),
('K5-2-u5-C3','kor',5,2,'u5',1,'생활 속 추론 — 말하지 않아도 표정·몸짓·주변 모습을 단서로 상황이나 마음을 짐작하는 일도 추론이다',ARRAY['6국02-02 읽기']::text[],3),
('K5-2-u5-C4','kor',5,2,'u5',1,'단원의 흐름 — 추론하며 읽는 방법 알기 → 글쓴이의 생각 파악하기 → 함축된 표현 이해하기 → 글쓴이의 의도 파악하기 → 실천하기',ARRAY['6국02-02 읽기']::text[],4),
('K5-2-u5-C5','kor',5,2,'u5',2,'드러난 사실부터 — 추론하기 전에 먼저 글에 드러난 사실을 정확하게 파악한다',ARRAY['6국02-02 읽기']::text[],5),
('K5-2-u5-C6','kor',5,2,'u5',2,'글의 단서로 추론하기 — 글 속 여러 단서를 함께 놓고 생각해 드러나지 않은 내용을 짐작한다',ARRAY['6국02-02 읽기']::text[],6),
('K5-2-u5-C7','kor',5,2,'u5',2,'경험·지식으로 추론하기 — 배운 지식이나 겪은 경험을 떠올려 글에 쓰여 있지 않은 내용을 짐작한다',ARRAY['6국02-02 읽기']::text[],7),
('K5-2-u5-C8','kor',5,2,'u5',2,'근거와 함께 말하기 — 「~라는 단서로 보아」, 「~을 배운 적이 있어서」처럼 짐작한 까닭을 함께 말한다',ARRAY['6국02-02 읽기']::text[],8),
('K5-2-u5-C9','kor',5,2,'u5',2,'추론과 상상은 달라요 — 추론은 떠오르는 대로 지어내는 것이 아니라 단서와 경험·지식이라는 근거를 바탕으로 한다',ARRAY['6국02-02 읽기']::text[],9),
('K5-2-u5-C10','kor',5,2,'u5',2,'짐작은 여럿일 수 있어요 — 근거가 있으면 친구와 짐작이 달라도 견주어 볼 수 있고, 정답 맞히기보다 짐작하는 과정이 중요하다',ARRAY['6국02-02 읽기']::text[],10),
('K5-2-u5-C11','kor',5,2,'u5',4,'이야기 간추리기 — 사건을 다 늘어놓지 않고 중요한 장면만 골라 장면마다 인물의 행동과 변화를 한 문장으로 쓴다',ARRAY['6국02-01 읽기']::text[],11),
('K5-2-u5-C12','kor',5,2,'u5',4,'생략된 내용 추론하기 — 쓰인 사건 사이에 빠진 까닭이나 마음을 글의 단서와 경험·지식으로 채워 읽는다',ARRAY['6국02-02 읽기']::text[],12),
('K5-2-u5-C13','kor',5,2,'u5',4,'글쓴이의 생각 — 글을 통해 전하려는 생각으로, 글에 직접 쓰여 있지 않을 때가 많아 단서를 모아 짐작한다',ARRAY['6국02-01 읽기']::text[],13),
('K5-2-u5-C14','kor',5,2,'u5',4,'글쓴이의 생각을 찾는 단서 — 인물의 말과 행동, 이야기 끝에 일어난 변화, 제목을 단서로 삼는다',ARRAY['6국02-01 읽기']::text[],14),
('K5-2-u5-C15','kor',5,2,'u5',4,'인물의 마음과 분위기의 변화 — 장면마다 인물의 마음과 둘레의 분위기가 어떻게 달라지는지 살피며 읽는다',ARRAY['6국02-02 읽기']::text[],15),
('K5-2-u5-C16','kor',5,2,'u5',7,'문단의 중심 내용 간추리기 — 문단마다 중심 문장을 찾아 간추리면 글 전체의 내용이 보인다',ARRAY['6국02-01 읽기']::text[],16),
('K5-2-u5-C17','kor',5,2,'u5',7,'함축된 표현 — 뜻이 바로 드러나지 않고 숨겨져 있거나 하나의 표현에 여러 뜻이 담긴 표현',ARRAY['6국02-02 읽기']::text[],17),
('K5-2-u5-C18','kor',5,2,'u5',7,'사전에서의 뜻과 글에서의 뜻 — 함축된 표현은 사전에서의 뜻에서 출발해 글의 흐름에 맞는 글에서의 뜻으로 넓혀 읽는다',ARRAY['6국02-02 읽기']::text[],18),
('K5-2-u5-C19','kor',5,2,'u5',7,'어색한 곳이 신호 — 사전 뜻대로 읽어 글의 흐름에 맞지 않고 어색한 곳이 숨은 뜻을 찾아야 할 자리이다',ARRAY['6국02-02 읽기']::text[],19),
('K5-2-u5-C20','kor',5,2,'u5',7,'앞뒤 단서로 뜻 찾기 — 그 낱말 하나만 보지 않고 앞뒤 문장에서 숨은 뜻을 알려 주는 단서를 찾는다',ARRAY['6국02-02 읽기']::text[],20),
('K5-2-u5-C21','kor',5,2,'u5',7,'경험·지식으로 숨은 뜻 찾기 — 그 낱말에 대해 알고 있는 것과 겪은 일을 떠올리면 숨은 뜻이 더 분명해진다',ARRAY['6국02-02 읽기']::text[],21),
('K5-2-u5-C22','kor',5,2,'u5',7,'함축된 표현의 좋은 점 — 짧은 표현에 여러 뜻을 담아 생각과 마음을 생생하고 깊게 전하고, 읽는 사람이 더 깊이 생각하게 한다',ARRAY['6국02-02 읽기']::text[],22),
('K5-2-u5-C23','kor',5,2,'u5',9,'사건의 차례대로 간추리기 — 이야기를 주요 장면 중심으로 일어난 차례대로 간추리면 흐름이 보인다',ARRAY['6국02-01 읽기']::text[],23),
('K5-2-u5-C24','kor',5,2,'u5',9,'글쓴이의 의도 — 글쓴이가 독자에게 전하고 싶은 생각이나 바람, 곧 글을 쓴 까닭으로 글의 소재와는 다르다',ARRAY['6국02-02 읽기']::text[],24),
('K5-2-u5-C25','kor',5,2,'u5',9,'상황에 따라 달라지는 숨은 뜻 — 같은 말이라도 누가, 어떤 상황에서 했는지에 따라 담긴 숨은 뜻이 달라진다',ARRAY['6국02-02 읽기']::text[],25),
('K5-2-u5-C26','kor',5,2,'u5',9,'맞세운 표현 — 앉다와 일어서다처럼 반대되는 말을 맞세워 뜻을 또렷하게 전하기도 한다',ARRAY['6국02-02 읽기']::text[],26),
('K5-2-u5-C27','kor',5,2,'u5',9,'글쓴이의 의도를 찾는 단서 — 글의 중심 내용, 인물의 말에 담긴 함축된 표현, 되풀이되는 장면을 단서로 짐작한다',ARRAY['6국02-02 읽기']::text[],27),
('K5-2-u5-C28','kor',5,2,'u5',9,'인물의 말과 글쓴이의 의도 — 인물의 말은 이야기 속 상황에서 나온 말이고 의도는 글 전체로 전하려는 생각이라, 둘이 정반대일 수도 있다',ARRAY['6국02-02 읽기']::text[],28),
('K5-2-u5-C29','kor',5,2,'u5',9,'해석은 글 속 근거에 맞게 — 해석은 사람마다 다를 수 있지만 글 속 근거와 맞아야 하고, 맞지 않는 해석은 다시 살핀다',ARRAY['6국02-02 읽기']::text[],29),
('K5-2-u5-C30','kor',5,2,'u5',12,'감정을 함축된 표현으로 — 감정을 느낄 때 겪는 몸과 마음의 변화를 빗대어 말하면 감정의 깊이와 빛깔까지 전해진다',ARRAY['6국02-02 읽기']::text[],30),
('K5-2-u5-C31','kor',5,2,'u5',12,'감정 카드의 약속 — 앞면에는 감정을 그림으로, 뒷면에는 감정 낱말 없이 함축된 표현으로 쓴다',ARRAY['6국02-02 읽기']::text[],31),
('K5-2-u5-C32','kor',5,2,'u5',12,'짐작하고 확인하기 — 친구의 마음을 짐작한 뒤 맞는지 물어보고, 다르면 친구의 설명을 귀 기울여 듣는다',ARRAY['6국02-02 읽기']::text[],32),
('K5-2-u5-C33','kor',5,2,'u5',12,'공감하는 말 — 짐작한 마음에 맞추어 친구를 놀리지 않고 마음을 알아주는 말을 건넨다',ARRAY['6국02-02 읽기']::text[],33),
('K5-2-u5-C34','kor',5,2,'u5',14,'추론하며 읽기의 쓰임 — 추론하며 읽으면 글에 쓰인 것 너머까지 읽을 수 있고, 이 힘은 뉴스·광고·영상을 볼 때에도 필요하다',ARRAY['6국02-02 읽기']::text[],34),
('K5-2-u5-C35','kor',5,2,'u5',14,'ㅂ 소리가 덧나는 낱말 — 두 낱말이 어울릴 때 ㅂ 소리가 덧나면 소리 나는 대로 적는다 — 볍씨 · 햅쌀 · 멥쌀 · 좁쌀 (기초 다지기)',ARRAY['기초 다지기(소리가 덧나는 낱말)']::text[],35),
('K5-2-u5-C36','kor',5,2,'u5',14,'ㅎ 소리가 덧나는 낱말 — 두 낱말이 어울릴 때 ㅎ 소리가 덧나면 소리 나는 대로 적는다 — 수탉 · 암탉 · 머리카락 · 안팎 · 살코기 (기초 다지기)',ARRAY['기초 다지기(소리가 덧나는 낱말)']::text[],36)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-2-u5-X01','kor',5,'u5',ARRAY['K5-2-u5-C1']::text[],'글에 쓰여 있지 않은 내용은 알 수 없으니 짐작하면 안 된다고 여긴다','단서로 짐작해요'),
('K5-2-u5-X02','kor',5,'u5',ARRAY['K5-2-u5-C2']::text[],'추론을 글에 쓰인 문장을 그대로 찾아 옮기는 일로 여긴다','쓰여 있지 않은 것을 짐작'),
('K5-2-u5-X03','kor',5,'u5',ARRAY['K5-2-u5-C3']::text[],'추론은 글을 읽을 때만 하는 일이라 생활과는 관계없다고 여긴다','생활 속에서도 해요'),
('K5-2-u5-X04','kor',5,'u5',ARRAY['K5-2-u5-C4']::text[],'단원에서 배우는 차례를 섞거나 배울 내용과 하는 일을 엇갈리게 잇는다','방법 → 생각 → 표현 → 의도'),
('K5-2-u5-X05','kor',5,'u5',ARRAY['K5-2-u5-C5']::text[],'글에 드러난 사실을 확인하지 않고 바로 짐작부터 하거나 쓰여 있지 않은 것을 쓰여 있다고 여긴다','사실부터 정확히'),
('K5-2-u5-X06','kor',5,'u5',ARRAY['K5-2-u5-C6']::text[],'단서 하나만 보고 서둘러 짐작하거나 짐작과 관계없는 문장을 단서로 고른다','여러 단서를 함께'),
('K5-2-u5-X07','kor',5,'u5',ARRAY['K5-2-u5-C7','K5-2-u5-C21']::text[],'내 경험이나 지식은 글 읽기와 관계없다고 여겨 떠올리지 않는다','아는 것을 떠올려요'),
('K5-2-u5-X08','kor',5,'u5',ARRAY['K5-2-u5-C8']::text[],'짐작한 내용만 말하고 왜 그렇게 생각했는지 근거를 말하지 않는다','까닭을 함께'),
('K5-2-u5-X09','kor',5,'u5',ARRAY['K5-2-u5-C9']::text[],'추론을 아무렇게나 상상하는 일로 여겨 근거 없이 떠오르는 대로 지어낸다','근거가 있어야 추론'),
('K5-2-u5-X10','kor',5,'u5',ARRAY['K5-2-u5-C10']::text[],'추론에는 정답이 하나뿐이라 친구와 짐작이 다르면 한쪽은 반드시 틀렸다고 여긴다','근거가 있으면 견줘요'),
('K5-2-u5-X11','kor',5,'u5',ARRAY['K5-2-u5-C11']::text[],'이야기를 간추릴 때 작은 일까지 모두 늘어놓거나 중요하지 않은 장면을 고른다','중요한 장면만'),
('K5-2-u5-X12','kor',5,'u5',ARRAY['K5-2-u5-C12']::text[],'쓰인 사건만 읽고 사건 사이에 빠진 까닭이나 마음은 알 필요가 없다고 여긴다','빠진 까닭을 채워요'),
('K5-2-u5-X13','kor',5,'u5',ARRAY['K5-2-u5-C13']::text[],'글쓴이의 생각은 마지막 문장에 그대로 쓰여 있어 그 문장만 찾으면 된다고 여긴다','단서를 모아 짐작'),
('K5-2-u5-X14','kor',5,'u5',ARRAY['K5-2-u5-C14']::text[],'글쓴이의 생각을 짐작할 때 제목이나 이야기 끝의 변화를 살피지 않고 작은 사실 하나로 정한다','말 · 행동 · 변화 · 제목'),
('K5-2-u5-X15','kor',5,'u5',ARRAY['K5-2-u5-C15']::text[],'인물의 마음이나 분위기가 처음부터 끝까지 같다고 여겨 달라지는 모습을 놓친다','장면마다 달라져요'),
('K5-2-u5-X16','kor',5,'u5',ARRAY['K5-2-u5-C16']::text[],'문단의 중심 내용을 찾을 때 예를 든 문장이나 가장 긴 문장을 중심 문장으로 고른다','중심 문장을 찾아요'),
('K5-2-u5-X17','kor',5,'u5',ARRAY['K5-2-u5-C17']::text[],'함축된 표현을 사실과 다른 틀린 말이나 거짓말로 여긴다','숨은 뜻을 담은 표현'),
('K5-2-u5-X18','kor',5,'u5',ARRAY['K5-2-u5-C18']::text[],'함축된 표현을 사전에 나온 뜻 그대로만 읽는다','글에서의 뜻으로 넓혀요'),
('K5-2-u5-X19','kor',5,'u5',ARRAY['K5-2-u5-C19']::text[],'사전 뜻으로 읽어 어색한 곳이 있어도 그냥 지나친다','어색하면 멈춰요'),
('K5-2-u5-X20','kor',5,'u5',ARRAY['K5-2-u5-C20']::text[],'앞뒤 문장을 살피지 않고 그 낱말 하나만 보고 뜻을 정한다','앞뒤 단서를 봐요'),
('K5-2-u5-X21','kor',5,'u5',ARRAY['K5-2-u5-C21']::text[],'함축된 표현의 숨은 뜻을 짐작할 때 그 낱말에 대해 아는 것과 관계없는 경험을 떠올린다','뜻과 닿는 경험'),
('K5-2-u5-X22','kor',5,'u5',ARRAY['K5-2-u5-C22']::text[],'함축된 표현은 뜻을 어렵게 만들 뿐이라 쓸 까닭이 없다고 여긴다','생생하고 깊게 전해요'),
('K5-2-u5-X23','kor',5,'u5',ARRAY['K5-2-u5-C23']::text[],'이야기를 간추릴 때 사건의 차례를 뒤섞는다','일어난 차례대로'),
('K5-2-u5-X24','kor',5,'u5',ARRAY['K5-2-u5-C24']::text[],'글쓴이의 의도를 글의 소재(무엇에 대한 글인지)와 같은 것으로 여긴다','글을 쓴 까닭'),
('K5-2-u5-X25','kor',5,'u5',ARRAY['K5-2-u5-C25']::text[],'같은 말은 누가 어떤 상황에서 해도 뜻이 늘 같다고 여겨 겉뜻만 읽는다','누가 · 어떤 상황에서'),
('K5-2-u5-X26','kor',5,'u5',ARRAY['K5-2-u5-C26']::text[],'반대되는 말을 맞세운 표현을 앞뒤가 맞지 않는 틀린 문장으로 여긴다','맞세워 강조해요'),
('K5-2-u5-X27','kor',5,'u5',ARRAY['K5-2-u5-C27']::text[],'글쓴이의 의도를 짐작할 때 되풀이되는 장면이나 함축된 표현 같은 단서를 살피지 않는다','중심 내용 · 표현 · 반복'),
('K5-2-u5-X28','kor',5,'u5',ARRAY['K5-2-u5-C28']::text[],'글쓴이의 의도는 이야기 속 인물이 한 말과 똑같다고 여긴다','인물의 말 ≠ 의도'),
('K5-2-u5-X29','kor',5,'u5',ARRAY['K5-2-u5-C29']::text[],'해석은 사람마다 다르니 글 속 근거와 맞지 않아도 모두 알맞다고 여긴다','근거에 맞게'),
('K5-2-u5-X30','kor',5,'u5',ARRAY['K5-2-u5-C30']::text[],'감정은 「기뻐」, 「슬퍼」처럼 바로 말해야만 알아들을 수 있다고 여기거나 빗댄 표현의 감정을 잘못 짝짓는다','빗대면 더 깊어요'),
('K5-2-u5-X31','kor',5,'u5',ARRAY['K5-2-u5-C31']::text[],'감정 카드 뒷면에 감정 낱말을 그대로 쓰거나 앞면과 뒷면에 담을 것을 바꾼다','앞 그림 · 뒤 함축'),
('K5-2-u5-X32','kor',5,'u5',ARRAY['K5-2-u5-C32']::text[],'친구의 마음을 짐작한 뒤 확인하지 않고 내 짐작이 맞다고 우긴다','물어보고 들어요'),
('K5-2-u5-X33','kor',5,'u5',ARRAY['K5-2-u5-C33']::text[],'친구의 마음을 짐작만 하고 공감하는 말 없이 지나치거나 표현을 놀린다','마음을 알아주는 말'),
('K5-2-u5-X34','kor',5,'u5',ARRAY['K5-2-u5-C34']::text[],'추론하며 읽기는 국어 시간의 글에만 필요하고 뉴스·광고·영상과는 관계없다고 여긴다','어디에서나 필요해요'),
('K5-2-u5-X35','kor',5,'u5',ARRAY['K5-2-u5-C35']::text[],'ㅂ 소리가 덧나는 낱말을 원래 모양대로 「벼씨」, 「해쌀」, 「메쌀」, 「조쌀」로 적는다','볍씨 · 햅쌀 · 멥쌀 · 좁쌀'),
('K5-2-u5-X36','kor',5,'u5',ARRAY['K5-2-u5-C36']::text[],'ㅎ 소리가 덧나는 낱말을 원래 모양대로 「수닭」, 「암닭」, 「머리가락」, 「안밖」, 「살고기」로 적는다','수탉 · 암탉 · 안팎')
